e":"https://www.martsam.com/ (Accessed 2026-07-06)","timing":"November–March + Semana Santa","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"adventure","when":"November–March + Semana Santa","commission":"commissioned DMC guided excursion","accessed":"2026-07-06","wells":["activities"],"wells_basis":"pass 2 — text","si_all":["adventure"],"shelf_fit":{"adventure":"primary","culture":"destination"},"commission_lane":["DMC","guide"],"commission_embedded":false,"commission_basis":"lane"},{"name":"La Aurora Zoo","si_tag":"Family/Layover","zone":"13","tier":"essential","source":"https://en.wikipedia.org/wiki/Guatemala_City (Accessed 2026-07-06)","si":"family","commission":"non-commissionable admission; long-layover add-on","accessed":"2026-07-06","wells":[],"wells_basis":"text supports no Well — needs a human read","si_all":["Family/Layover","family"],"shelf_fit":{"Family/Layover":"evidenced","culture":"destination","family":"primary"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed","si_raw":"Family/Layover","si_map_basis":"normalised from free text ''Family/Layover'' by gen_normalise_jewel_si"}],"faq":[{"q":"Should I stay in Guatemala City or head straight to Antigua?","a":"Treat Guatemala City as a 1–2-night stopover, not a leisure anchor. It''s the international gateway — La Aurora (Central America''s 4th-busiest, 4,919,850 pax in 2024) sits in Zone 13, ~45–60 minutes (~40–45 km) from Antigua — so most travelers rest a night, then road out to the country''s true anchors.","source":"en.wikipedia.org, Accessed 2026-07-06","si_tag":null},{"q":"Is Guatemala City worth a stop for museums?","a":"Yes, for a half-day. The museum cluster is genuinely first-rate: Museo Popol Vuh holds one of the country''s best pre-Hispanic and colonial-art collections, and Museo Ixchel holds ~8,000 textile pieces from 180+ Indigenous communities, both on the UFM campus in the safe Zone 10.","source":"museoixchel.org, Accessed 2026-07-06","si_tag":"culture"},{"q":"How do I get from the airport safely?","a":"Use arranged or vetted transport, or Uber — never a street-hailed taxi. Move from La Aurora (Zone 13) to Zone 10/14 lodging on pre-arranged transport, avoid walking at night in unfamiliar zones, and ride the onward Antigua/Atitlán/Tikal handoff on a vetted shuttle or the DMC''s own transport.","source":"https://www.gov.uk/foreign-travel-advice/guatemala","si_tag":"safety"}],"seo":{"meta_title":"Guatemala City Travel Guide — La Aurora Gateway, Zona Viva & Safe-Zone Stopover | TravelWell.World","meta_description":"Accurate guide to Guatemala City as the international gateway (GUA) to Antigua, Atitlán & Tikal — Zona Viva stays, museum cluster, safety zones, route-around.","search_language":["en","es-GT"],"local_keywords":["qué hacer en Ciudad de Guatemala","Zona Viva hoteles","escala Guatemala City","Museo Ixchel Zona 10","traslado aeropuerto La Aurora a Antigua","zonas seguras Ciudad de Guatemala"],"hreflang":["en","es-GT"],"jsonld_type":"TouristDestination","content_freshness":"2026-07-06","attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-07-06","last_verified_basis":"source_verified","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/guatemala","read":"2026-08-20T14:47:53Z","source_updated":"2026-08-13T14:45:16+01:00"}]},"long_tail":["Guatemala City stopover before Antigua","is Guatemala City safe Zona Viva Zone 10","La Aurora airport to Antigua transfer","best hotels Zona Viva Guatemala City","Guatemala travel advisory Zone 18 Villa Nueva"]},"booking":{"advisory_updated":"2026-08-20","advisory_authority":"FCDO"},"si_checklist_25":null,"sis_present":["Culture & Heritage (future)"],"ultra":[{"property":"Westin Camino Real (Zone 10)","play":"premier gateway night","channel":"Fora/Virtuoso consortia; else GDS commissioned","mor":"Fora advisor","tier":"premier"},{"property":"InterContinental Guatemala (Zone 10)","play":"business-luxury gateway","channel":"IHG consortia / Fora","mor":"Fora/consortia","tier":"premier"},{"property":"Barceló Guatemala City (Zone 10)","play":"upper premier gateway","channel":"consortia / GDS","mor":"consortia","tier":"premier"},{"property":"Hyatt Centric (Zone 10)","play":"lifestyle premier gateway","channel":"Hyatt Privé / Fora","mor":"Fora/Privé","tier":"premier"},{"property":"Antigua boutique-colonial base (REDIRECT)","play":"the true ultra stay — GC is transit","channel":"Fora/Virtuoso Antigua portfolio","mor":"Fora advisor","tier":"ultra"}],"source_verified":"2026-07-06","hero":{"query":"Guatemala City, Guatemala"},"geo":{"lat":14.6349,"lng":-90.5069},"orbit":[{"id":"antigua-guatemala","jewels":12,"si":["expedition","culture","culinary","wildlife"]},{"id":"lake-atitlan-guatemala","jewels":11,"si":["adventure","romance","culture","wellness"]},{"id":"semuc-champey-guatemala","jewels":6,"si":["expedition"]},{"id":"tikal-guatemala","jewels":9,"si":["expedition","culture"]}],"orbit_country":[]}'::jsonb, 45),
  ('holbox-mexico', '10S', 'Holbox', 'Mexico', 'Holbox whale sharks', 'live', 'verified', 'tropicalBeach', 'Quintana Roo (Cancún & Riviera Maya)', '{"expedition","romance","ocean","wildlife"}', '{}', '{"essential","comfort"}', null, null, '{"key_facts":["Whale-shark season mid-May to mid-Sep (official May 15-Sep 17), gov-enforced","Snorkel-only, no-touch; two swimmers + guide per turn; CONANP-certified operators only","Car-free island reached by ferry from Chiquila; golf carts/mopeds only","Bioluminescence at Punta Cocos on dark nights (western tip)","Inside Yum Balam Flora & Fauna Protection Area (~90% of Yucatan endemic birds)"],"safety":{"emergency":"911","hospital":"small local health center on-island; serious cases evac by ferry+road to Cancun private hospitals or air-evac","malaria":"effectively none in tourist zone","dengue":"active - Quintana Roo among highest-activity states 2026; chikungunya/Zika circulate; mangrove mosquitoes","water":"bottled/purified only","hurricane":"Jun-Nov - overlaps whale-shark peak","whale_shark":"SNORKEL ONLY, no-touch; life jackets typically mandatory; seasickness common (open water); biodegradable reef-safe sunscreen mandatory; CONANP-licensed operator required","fcdo":{"posture":"AREA-RESTRICTED","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-08-20T14:49:02Z","page_updated":"2026-07-16T16:08:09+01:00","source_country":"mexico","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely","fcdo_zones":[{"name":"The city of Tijuana, in Baja California","lvl":3,"posture":"all-but-essential","except":["airside transit through Tijuana airport","the Cross Border Xpress bridge linking the airport across the border","federal toll road 1D and the Via Rápida through Tijuana to the border"]},{"name":"The city of Tecate in Baja California, including roads between Tijuana and Tecate","lvl":3,"posture":"all-but-essential"},{"name":"The state of Chihuahua","lvl":3,"posture":"all-but-essential","except":["the city of Chihuahua","the border crossing in Ciudad Juárez via federal toll road 45","federal toll road 45D between Chihuahua and Ciudad Juárez","the Copper Canyon rail route and the towns immediately on it, including Creel","the road from Creel via San Juanito to San Pedro","state highway 16 from San Pedro to Chihuahua"],"note":"The advisory also covers the areas south-west of road 45D."},{"name":"The state of Sinaloa","lvl":3,"posture":"all-but-essential","except":["the cities of Los Mochis and Mazatlán","road 32 between El Fuerte and Los Mochis","the 15D federal toll road running the length of the state","the Copper Canyon rail route to and from Los Mochis and El Fuerte, and the towns immediately on it"]},{"name":"The state of Tamaulipas","lvl":3,"posture":"all-but-essential","except":["the border crossing at Nuevo Laredo via federal toll road 85D from Monterrey","federal highways 80, 81 and 85 between Tampico, Ciudad Victoria and Magueyes","the area of Tamaulipas south of those highways"]},{"name":"The state of Zacatecas","lvl":3,"posture":"all-but-essential"},{"name":"In Guanajuato: the areas south-west of road 45D","lvl":3,"posture":"all-but-essential","note":"FCDO advises against all but essential travel to the areas south-west of road 45D. (San Miguel de Allende and Guanajuato City sit outside this area.)"},{"name":"The state of Michoacán","lvl":3,"posture":"all-but-essential","except":["the city of Morelia via federal toll roads 15D, 126 and 43","toll road 48D between Morelia and its airport","the town of Pátzcuaro via toll roads 14D and 15 from Morelia, and boat trips on Lake Pátzcuaro","Federal Highway 15D"]},{"name":"In Jalisco: the areas south and south-west of Lake Chapala to the Colima border","lvl":3,"posture":"all-but-essential","note":"Thirty-nine named municipalities, including Autlán de Navarro, Sayula, Tapalpa, Cocula and Villa Corona — the advisory lists each by name."},{"name":"In Jalisco: eleven northern municipalities","lvl":3,"posture":"all-but-essential","note":"Bolaños, Chimaltitán, Colotlán, Hostotipaquillo, Huejúcar, Huequilla el Alto, Mezquitic, San Martín de Bolaños, Santa María de los Ángeles, Totatiche and Villa Guerrero."},{"name":"The state of Colima","lvl":3,"posture":"all-but-essential","except":["the city of Manzanillo by sea, or by air via Manzanillo-Costalegre International Airport","direct travel via road 200 from that airport to Manzanillo"]},{"name":"The state of Guerrero, including the city of Acapulco","lvl":3,"posture":"all-but-essential","except":["the town of Zihuatanejo/Ixtapa accessed by air"]},{"name":"Within 40km of the Guatemalan border, from the Pacific Coast up to and including the Gracias a Dios crossing","lvl":3,"posture":"all-but-essential"},{"name":"Federal Highway 199 between Rancho Nuevo, outside San Cristóbal de las Casas, and the Chancalá junction outside Palenque","lvl":3,"posture":"all-but-essential","note":"The restriction is the highway segment, not the towns at either end."}],"fcdo_zones_provenance":{"file":"src/data/safety.json","ref":"f8666636bc25790e0c9643ad5656f8d9fea37bf6","ref_committed":"2026-08-30T05:44:55Z","country_iso2":"MX","summary":"The FCDO advises against all but essential travel to named states, cities and border areas of Mexico — listed below in its own words, each with its own exceptions. The Yucatán Peninsula, Mexico City, Baja California Sur and the other main visitor regions carry no FCDO restriction.","source":"UK FCDO — Mexico travel advice, reviewed 2026-07-16 (verbatim snapshot from the research library)","_rule":"the FCDO restricted-area records for this country, verbatim. PRESENCE OF THIS BLOCK IS NOT A CLAIM THAT THIS DESTINATION SITS IN ANY OF THEM — membership is a coverage judgement and is set only in `zone_record`, by a human."}},"timing":{"peak":"Dec-Apr (dry high season, northern-winter escape); event peak mid-May-mid-Sep whale sharks (peak Jul-Aug)","shoulder":"May, Jun, Sep (whale sharks present, rainy-season variability, softer rates)","green":"Oct (rainiest, many closures) + late Sep-Nov; November is the underrated value window","out_of_season_fill_the_beds":"bioluminescence (new-moon year-round), Cabo Catoche/Isla Pasion boat tours, Yum Balam birding, kite season from Nov, boutique value rates","flag":"whale-shark event peak OVERLAPS hurricane season (Jun-Nov, peak Aug-Oct) - sell with trip insurance + weather caveat","sources":["https://girlonazebra.com/best-time-to-visit-isla-holbox/","https://www.casasandra.com/blog/best-time-to-visit-holbox","https://puntacaliza.com/whale-sharks-in-holbox-best-season-and-tips-for-sightings/","https://www.islaholbox-info.com/en/holbox-island/travel-time-and-climate/"],"fire_date":"whale-shark campaigns Feb-Mar; dry-season/honeymoon campaigns Aug-Oct prior year; Nov green-window value late summer","event_peaks":"Christmas-New Year, Semana Santa (Easter ~2x February rate), whale-shark peak Jul-Aug","booking_lead":"3-6 months for Dec-Apr peak; tiny boutique inventory; book whale-shark tours ahead in event peak"},"jewels":[{"name":"Whale-shark snorkel aggregation","si_tag":"Global Expedition Adventures","status":"live","tier":"comfort","bookable":"CONANP-licensed full-day snorkel tour","source":"https://travelyucatan.com/whale-sharks-holbox/","hook":"swim beside the world''s largest fish in a controlled, no-touch encounter","si":"expedition","blurb":"swim beside the world''s largest fish in a controlled, no-touch encounter","commission":"local operator + Olympus/Amstar DMC + Viator affiliate","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["expedition","wildlife"],"shelf_fit":{"expedition":"primary","ocean":"destination","romance":"destination","wildlife":"evidenced"},"commission_lane":["operator","DMC","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Punta Cocos bioluminescence night","si_tag":"Romance & Honeymoons","status":"live","tier":"essential","bookable":"guided bioluminescence tour","source":"https://sceneloc8.com/isla-holbox-a-car-free-paradise-of-beaches-and-bioluminescence/","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"plankton glow on the western tip on dark, moonless nights","si":"romance","blurb":"plankton glow on the western tip on dark, moonless nights","when":"Dec-Apr","commission":"local operator + Viator affiliate","wells":["stay"],"wells_basis":"derived from name/blurb/hook","si_all":["romance"],"shelf_fit":{"expedition":"destination","ocean":"destination","romance":"primary","wildlife":"destination"},"commission_lane":["operator","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Cabo Catoche / Isla Pasion three-islands boat tour","si_tag":"Ocean Adventures","status":"future","tier":"comfort","bookable":"boat/snorkel tour","source":"https://www.islaholbox-info.com/en/activities/tours-on-holbox/","timing":"Dec-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"ocean","when":"Dec-Apr","commission":"local operator + GYG affiliate","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["ocean"],"shelf_fit":{"expedition":"destination","ocean":"primary","romance":"destination","wildlife":"destination"},"commission_lane":["operator","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Yum Balam reserve birding + flamingos","si_tag":"Wildlife & Nature","status":"future","tier":"essential","bookable":"eco/kayak tour","source":"https://en.wikipedia.org/wiki/Isla_Holbox","hook":"~90% of Yucatán endemic birds; flamingos, crocodiles, in a protected mangrove reserve","si":"wildlife","blurb":"~90% of Yucatán endemic birds; flamingos, crocodiles, in a protected mangrove reserve","commission":"local operator + DMC","wells":["activities"],"wells_basis":"pass 2 — text","si_all":["wildlife"],"shelf_fit":{"expedition":"destination","ocean":"destination","romance":"destination","wildlife":"primary"},"commission_lane":["operator","DMC"],"commission_embedded":false,"commission_basis":"lane"}],"faq":[{"q":"What''s the real risk to plan for in Holbox?","a":"Open-water seasickness, mosquitoes and hurricane timing — not crime. Whale-shark boats run into open ocean where swells cause common seasickness (take motion meds 30–60 min before departure); this is a mangrove island so dengue is active (use repellent); and the whale-shark peak (Jul–Aug) overlaps hurricane season (Jun–Nov, peak Aug–Oct), so insure the trip.","source":"https://www.gov.uk/foreign-travel-advice/mexico","si_tag":"safety"},{"q":"When and how can I swim with whale sharks in Holbox?","a":"Between May 15 and Sep 17, peaking July–August, on a full-day morning boat departure with a CONANP-licensed operator. The encounter is snorkel-only beside the world''s largest fish, with just two swimmers and a guide in the water at a time — book ahead during the event peak, as demand is high and operators are capped.","source":"travelyucatan.com, 2026-07-04","si_tag":"expedition"},{"q":"What is Holbox like as a car-free island?","a":"It is a barefoot sandbar with sand streets and no cars — you arrive by ferry from Chiquilá and move around by golf cart or moped. That car-free rhythm is the point: it is the slow, bohemian antidote to Cancún, built for beach days, bikes and sunsets rather than nightlife strips.","source":"en.wikipedia.org, 2026-07-04","si_tag":"tropical"},{"q":"Is Holbox good for a honeymoon?","a":"Yes, for couples who want quiet design over resort scale. There are no mass all-inclusives — just artist-owned boutiques like Ser Casasandra (17 rooms + 1 villa) and Punta Caliza (12 rooms) — plus bioluminescent night swims at Punta Cocos. Because inventory is tiny, book 3–6 months ahead for the Dec–Apr peak.","source":"casasandra.com / puntacaliza.com, 2026-07-04","si_tag":"romance"},{"q":"What else is there to do in Holbox beyond whale sharks?","a":"Plenty year-round. Walk the bioluminescent shore at Punta Cocos on new-moon nights, take the Cabo Catoche / Isla Pasión \"three islands\" boat-and-snorkel tour, kayak the mangroves, or ride the kite-surf season that starts in November — the reasons to come when the whale sharks are gone.","source":"islaholbox-info.com / sceneloc8.com, 2026-07-04","si_tag":"ocean"},{"q":"What wildlife can I see in the Yum Balam reserve?","a":"A lot — Holbox sits inside the Yum Balam Flora & Fauna Protection Area, home to roughly 90% of the Yucatán''s endemic bird species, plus flamingos, crocodiles and turtles. Guided eco or kayak tours through the protected mangroves are the way to see them; birdlife is seasonal, so ask what''s present at your dates.","source":"en.wikipedia.org, 2026-07-04","si_tag":"wildlife"},{"q":"When is the best time to visit Holbox?","a":"December–April is the dry high season (blue skies, busiest); the whale-shark window is mid-May to mid-September. November is the underrated value pick — dry-season comfort, clean beaches and the start of kite season at low-season prices — while October is rainiest and many venues close. Easter rates run about double February.","source":"girlonazebra.com / islaholbox-info.com, 2026-07-04","si_tag":"planning"}],"seo":{"meta_title":"Holbox Whale Sharks: Car-Free Island Guide","meta_description":"Snorkel with whale sharks off car-free Isla Holbox (mid-May–mid-Sep, no-touch, licensed operators) then walk a bioluminescent shore at Punta Cocos. When and how.","slug":"holbox-mexico","primary_keyword":"Holbox whale sharks","long_tail":["Holbox whale shark season 2026","Holbox bioluminescence Punta Cocos","car-free island Yucatan","Yum Balam biosphere Holbox","Holbox whale shark snorkel rules"],"search_language":["en","es-MX"],"local_keywords":["tiburón ballena Holbox","nadar con tiburón ballena Holbox temporada","isla sin autos Holbox","bioluminiscencia Punta Cocos","reserva Yum Balam Holbox","tours Holbox Cabo Catoche Isla Pasión","hoteles boutique Holbox"],"hreflang":["en","es-MX"],"jsonld_type":"TouristDestination","content_freshness":"2026-07-04","attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-07-04","last_verified_basis":"source_verified","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-08-20T14:49:02Z","source_updated":"2026-07-16T16:08:09+01:00"}]}},"booking":{"advisory_updated":"2026-08-20","advisory_authority":"FCDO"},"si_checklist_25":null,"sis_present":[{"si":"expedition","status":"live"},{"si":"romance","status":"live"},{"si":"ocean","status":"future"},{"si":"wildlife","status":"future"}],"ultra":[{"name":"Ser Casasandra","posture":"boutique-luxe (not branded ultra)","price_tier":"luxury","earning":"on application / host-Virtuoso or host-DMC block","direct_only":true,"mor":"commissionable only where offered; no net-rate resale","source":"https://www.casasandra.com/"},{"name":"Punta Caliza","posture":"boutique-luxe (12-room design boutique, not a chain)","price_tier":"luxury","earning":"on application / host-Virtuoso","direct_only":true,"mor":"no net-rate resale","source":"https://puntacaliza.com/whale-sharks-in-holbox-best-season-and-tips-for-sightings/"},{"name":"Villas HM Palapas del Mar","posture":"boutique-luxe (HM Hotels group, resort-shaped)","price_tier":"premier","earning":"on application; some bedbank/TAAP possible - verify terms","direct_only":false,"mor":"no net-rate resale","source":""},{"name":"Ser Casasandra luxury villa","posture":"closest to ultra buy-out on-island","price_tier":"ultra","earning":"on application / host-Virtuoso","direct_only":true,"mor":"no net-rate resale","source":"https://www.casasandra.com/"}],"source_verified":"2026-07-04","hero":{"query":"Holbox, Mexico"},"geo":{"lat":21.522,"lng":-87.379},"orbit":[{"id":"akumal-mexico","jewels":5,"si":["diveglobal","ocean","culture"]},{"id":"bacalar-mexico","jewels":6,"si":["tropical","wellness","adventure"]},{"id":"cancun-mexico","jewels":5,"si":["tropical","adventure","diveglobal","ocean"]},{"id":"coba-mexico","jewels":5,"si":["culture","expedition","family"]},{"id":"cozumel-mexico","jewels":5,"si":["diveglobal","liveaboard","ocean"]},{"id":"isla-contoy-mexico","jewels":3,"si":["expedition","ocean","wildlife"]},{"id":"isla-mujeres-mexico","jewels":5,"si":["tropical","ocean","diveglobal","adventure"]},{"id":"mahahual-mexico","jewels":5,"si":["liveaboard","diveglobal"]},{"id":"playa-del-carmen-mexico","jewels":5,"si":["romance","expedition","diveglobal","culture"]},{"id":"puerto-aventuras-mexico","jewels":5,"si":["romance","diveglobal","ocean","wildlife"]},{"id":"puerto-morelos-mexico","jewels":5,"si":["diveglobal","ocean","adventure","culinary"]},{"id":"sian-kaan-mexico","jewels":5,"si":["expedition","wildlife","tropical"]},{"id":"tulum-mexico","jewels":5,"si":["expedition","diveglobal","culture","wildlife"]}],"orbit_country":["balandra-beach-mexico","cabo-pulmo-mexico","cabo-san-lucas-mexico","calakmul-mexico","campeche-city-mexico","careyes-mexico","celestun-mexico","chapala-ajijic-mexico","chichen-itza-mexico","costalegre-mexico","east-cape-mexico","ensenada-mexico","espiritu-santo-island-mexico","guadalajara-mexico","guanajuato-city-mexico","huatulco-mexico","izamal-mexico","la-paz-mexico","loreto-mexico","los-barriles-mexico","magdalena-bay-mexico","mazamitla-mexico","merida-mexico","mexico-city-mexico","oaxaca-city-mexico","palenque-mexico","puerto-vallarta-mexico","punta-mita-mexico","rio-lagartos-mexico","san-cristobal-de-las-casas-mexico","san-jose-del-cabo-mexico","san-miguel-de-allende-mexico","san-sebastian-del-oest