tch","si_tag":"Wildlife & Nature","status":"future","tier":"comfort","hook":"Humpbacks Dec 15-Mar 21 (97% success at peak); year-round dolphins/turtles.","bookable_category":"wildlife boat safari","source":"https://seasafarihuatulco.com/whale-watching-tours/","si":"wildlife","blurb":"Humpbacks Dec 15-Mar 21 (97% success at peak); year-round dolphins/turtles.","commission":"operator affiliate / DMC ~12%","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["ocean","wildlife"],"shelf_fit":{"culture":"destination","diveglobal":"destination","expedition":"destination","ocean":"evidenced","wellness":"destination","wildlife":"primary"},"commission_pct_low":12,"commission_pct_high":12,"commission_lane":["operator","DMC","affiliate"],"commission_embedded":false,"commission_basis":"band+lane"},{"name":"Cacaluta & San Agustin remote bays","si_tag":"Ocean Adventures","status":"future","tier":"comfort","hook":"Wild, undeveloped bays — heart-shaped Cacaluta and gin-clear San Agustin (18 m viz).","bookable_category":"private boat / dedicated tour","source":"https://www.tripadvisor.com/Attraction_Review-g150789-d524145-Reviews-Bahia_de_Cacaluta-Huatulco_Southern_Mexico.html","timing":"Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"ocean","blurb":"Wild, undeveloped bays — heart-shaped Cacaluta and gin-clear San Agustin (18 m viz).","when":"Nov-Apr","commission":"DMC / operator affiliate; park bracelet pass-through","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["expedition","ocean"],"shelf_fit":{"culture":"destination","diveglobal":"destination","expedition":"evidenced","ocean":"primary","wellness":"destination","wildlife":"destination"},"commission_lane":["operator","DMC","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"La Entrega / San Agustin reef dive","si_tag":"Dive Globally","status":"future","tier":"comfort","hook":"Beginner-to-intermediate protected-reef dives; San Agustin ~30 m sunken ship.","bookable_category":"reef dive (PADI operator)","source":"https://www.explorehuatulco.com/Huatulco-Scuba-Diving-Guide","timing":"Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"diveglobal","blurb":"Beginner-to-intermediate protected-reef dives; San Agustin ~30 m sunken ship.","when":"Nov-Apr","commission":"dive-operator affiliate / DMC ~12%","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["diveglobal"],"shelf_fit":{"culture":"destination","diveglobal":"primary","expedition":"destination","ocean":"destination","wellness":"destination","wildlife":"destination"},"commission_pct_low":12,"commission_pct_high":12,"commission_lane":["operator","DMC","affiliate"],"commission_embedded":false,"commission_basis":"band+lane"},{"name":"Pluma Hidalgo coffee-finca day","si_tag":"Wellness","status":"future","tier":"comfort","hook":"45-min drive to ~1,350 m coffee country — finca tour, roasting, tasting, mirador views.","bookable_category":"guided coffee tour","source":"https://www.getyourguide.com/huatulco-l781/huatulco-santa-maria-and-pluma-hidalgo-coffee-tour-t631983/","timing":"Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"wellness","blurb":"45-min drive to ~1,350 m coffee country — finca tour, roasting, tasting, mirador views.","when":"Nov-Apr","commission":"affiliate 4-8% / DMC ~12%","wells":["move","activities"],"wells_basis":"derived from name/blurb/hook","si_all":["wellness"],"shelf_fit":{"culture":"destination","diveglobal":"destination","expedition":"destination","ocean":"destination","wellness":"primary","wildlife":"destination"},"commission_pct_low":4,"commission_pct_high":8,"commission_lane":["DMC","affiliate"],"commission_embedded":false,"commission_basis":"band+lane"},{"name":"Copalita eco-archaeological park","si_tag":"Culture & Heritage","status":"future","tier":"essential","hook":"One of only two seaside archaeological sites in Mexico — Zapotec/Mixtec city in rainforest above the river mouth.","bookable_category":"guided park visit / combo","source":"https://lugares.inah.gob.mx/en/node/4487","timing":"year-round","timing_type":"ALWAYS-ON","si":"culture","blurb":"One of only two seaside archaeological sites in Mexico — Zapotec/Mixtec city in rainforest above the river mouth.","when":"year-round","commission":"affiliate 4-8% / DMC ~12%; park entry pass-through","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["culture"],"shelf_fit":{"culture":"primary","diveglobal":"destination","expedition":"destination","ocean":"destination","wellness":"destination","wildlife":"destination"},"commission_pct_low":4,"commission_pct_high":8,"commission_lane":["DMC","affiliate"],"commission_embedded":false,"commission_basis":"band+lane"},{"name":"La Crucecita zocalo + Church of Guadalupe","si_tag":"Culture & Heritage","status":"future","tier":"essential","hook":"Real Oaxacan town with a zocalo, market, and one of Mexico''s largest Guadalupe ceiling murals.","bookable_category":"walking tour / DIY","source":"https://www.explorehuatulco.com/la-crucecita-region-huatulco-mexico","timing":"year-round","timing_type":"ALWAYS-ON","si":"culture","blurb":"Real Oaxacan town with a zocalo, market, and one of Mexico''s largest Guadalupe ceiling murals.","when":"year-round","commission":"affiliate on guided walks; DIY non-commissionable","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["culture"],"shelf_fit":{"culture":"primary","diveglobal":"destination","expedition":"destination","ocean":"destination","wellness":"destination","wildlife":"destination"},"commission_lane":["affiliate","guide"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Copalita River rafting","si_tag":"Global Expedition Adventures","status":"live","tier":"comfort","hook":"Guided whitewater at La Bocana beside the archaeological site; fuller in green months.","bookable_category":"guided rafting","source":"https://www.huatulcowatersports.com/tours/copalita-archaological-site-143783","timing":"Nov-Apr","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","blurb":"Guided whitewater at La Bocana beside the archaeological site; fuller in green months.","when":"Nov-Apr","commission":"operator affiliate / DMC ~12%","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["culture","expedition"],"shelf_fit":{"culture":"evidenced","diveglobal":"destination","expedition":"primary","ocean":"destination","wellness":"destination","wildlife":"destination"},"commission_pct_low":12,"commission_pct_high":12,"commission_lane":["operator","DMC","affiliate"],"commission_embedded":false,"commission_basis":"band+lane"}],"faq":[{"q":"What''s the real risk to plan for in the water?","a":"Riptides on the open beaches, not the sheltered bays. The horseshoe coves (La Entrega, Maguey, San Agustín) are genuinely calm and swimmable, but open stretches of Tangolunda and Chahué carry rip currents — swim only the flagged, sheltered coves, and heed the flags.","source":"mrplayas.com, 2026-07-07","si_tag":"safety"},{"q":"Which bays are calm enough for swimming and families?","a":"The horseshoe coves. La Entrega is the best land-accessible snorkel cove — the reef starts feet from shore — and Maguey, Órgano and San Agustín stay calm inside their coves; that''s the difference from surf-driven Puerto Escondido up the coast.","source":"mrplayas.com / secretflying.com, 2026-07-07","si_tag":"tropical"},{"q":"What''s the one must-do day here?","a":"The nine-bays boat tour — a full-day (~7 h) expedition across the nine bays with beach and snorkel stops, bookable through Amstar''s \"Sea and Sun\"/\"Seven Bays\" excursions or affiliate marketplaces (the National Park conservation bracelet is a cash pass-through).","source":"amstardmc.com, 2026-07-07","si_tag":"expedition"},{"q":"When can I see whales?","a":"Humpbacks run **Dec 15–Mar 21**, with sightings on **over 97% of tours** at the peak, on boat safaris out of Santa Cruz; dolphins and turtles are year-round, and turtle nesting (olive-ridley/green) runs Jul–Jan.","source":"oceanico.org, 2026-07-07","si_tag":"wildlife"},{"q":"Can beginners dive the reef here?","a":"Yes — the protected Pacific reef is beginner-friendly. La Entrega runs 10–12 m and San Agustín adds a ~30 m sunken ship for advanced divers, with up to ~18 m visibility in the dry season; book only PADI-certified operators (Huatulco Dive Center, Anfibios, Hurricane Divers).","source":"explorehuatulco.com, 2026-07-07","si_tag":"diveglobal"},{"q":"Is there culture beyond the beach?","a":"Yes — Copalita is one of only two seaside archaeological sites in Mexico (with Tulum), a Zapotec/Mixtec city settled by ~500 BC in rainforest above the river mouth, and La Crucecita''s zócalo holds one of Mexico''s largest Guadalupe ceiling murals.","source":"lugares.inah.gob.mx, 2026-07-07","si_tag":"culture"},{"q":"Is Huatulco good for a honeymoon?","a":"Yes, for calm-bay romance rather than branded-ultra. Secrets Huatulco is the adults-only, all-oceanfront-suite anchor of the Tangolunda strip; the coast tops out at premier all-inclusive plus a top oceanfront villa in Conejos — there is no Aman/Rosewood-tier hotel here.","source":"hyattinclusivecollection.com, 2026-07-07","si_tag":"romance"}],"seo":{"meta_title":"Huatulco Travel Guide 2026 — Nine Bays, Snorkel & Coffee Country | TravelWell.World","meta_description":"Plan Huatulco, Oaxaca''s calm eco-resort coast: the nine-bays boat tour, Maguey/Organo snorkel, La Crucecita, Pluma Hidalgo coffee, Copalita eco-archaeology, whale season, safety (Huatulco unrestricted).","slug":"huatulco-mexico","jsonld_type":"TouristDestination","content_freshness":"2026-07-07","search_language":"es-MX","local_keywords":["qué hacer en Huatulco","Bahías de Huatulco","La Crucecita","tour de las nueve bahías Huatulco","snorkel en Bahía Maguey","café Pluma Hidalgo tour","Parque Eco-Arqueológico Copalita","avistamiento de ballenas Huatulco","mejor época para visitar Huatulco","buceo en Huatulco","villas frente al mar Conejos Huatulco"],"hreflang":["en","es-MX"],"attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-07-07","last_verified_basis":"source_verified","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-08-20T14:49:02Z","source_updated":"2026-07-16T16:08:09+01:00"}]}},"booking":{"advisory_updated":"2026-08-20","advisory_authority":"FCDO"},"si_checklist_25":null,"sis_present":[{"si":"expedition","status":"live"},{"si":"diveglobal","status":"future"},{"si":"ocean","status":"future"},{"si":"culture","status":"future"},{"si":"wildlife","status":"future"},{"si":"wellness","status":"future"}],"ultra":[{"name":"Secrets Huatulco Resort & Spa","price_tier":"premier","virtuoso":false,"earning":"all-incl -> OA host AOR + Hyatt Inclusive TA ~12%","mor_posture":true,"note":"adults-only all-oceanfront-suite; the branded ceiling for the coast","source":"https://www.hyattinclusivecollection.com/en/resorts-hotels/secrets/mexico/huatulco-resort-spa/"},{"name":"Dreams Huatulco Resort & Spa","price_tier":"comfort-premier","virtuoso":false,"earning":"OA host AOR + Hyatt Inclusive TA ~12%","mor_posture":true,"note":"family sister with shared Secrets access","source":"https://www.tripadvisor.com/Hotel_Review-g150789-d2089597-Reviews-Secrets_Huatulco_Resort_Spa-Huatulco_Southern_Mexico.html"},{"name":"Las Palmas Resort","price_tier":"comfort","virtuoso":false,"earning":"OA host AOR","mor_posture":true,"source":"https://www.tripadvisor.com/ShowTopic-g150789-i740-k14655958-Secrets_vs_Dreams_vs_Barcelo-Huatulco_Southern_Mexico.html"},{"name":"Boutique bay villas — Residencial Conejos (oceanfront)","price_tier":"ultra","virtuoso":false,"earning":"on application / via host or DMC villa AOR","mor_posture":true,"note":"villa ceiling; no branded true-ultra hotel on this eco-resort coast; net-rate resale red","source":"https://www.airbnb.com/santa-maria-huatulco-mexico/stays/villas"}],"source_verified":"2026-07-07","hero":{"query":"Huatulco, Mexico"},"geo":{"lat":15.76,"lng":-96.13},"orbit":[{"id":"oaxaca-city-mexico","jewels":14,"si":["romance","expedition"]},{"id":"puerto-escondido-mexico","jewels":10,"si":["expedition","romance","tropical","wildlife","culture"]}],"orbit_country":["akumal-mexico","bacalar-mexico","balandra-beach-mexico","cabo-pulmo-mexico","cabo-san-lucas-mexico","calakmul-mexico","campeche-city-mexico","cancun-mexico","careyes-mexico","celestun-mexico","chapala-ajijic-mexico","chichen-itza-mexico","coba-mexico","costalegre-mexico","cozumel-mexico","east-cape-mexico","ensenada-mexico","espiritu-santo-island-mexico","guadalajara-mexico","guanajuato-city-mexico","holbox-mexico","isla-contoy-mexico","isla-mujeres-mexico","izamal-mexico","la-paz-mexico","loreto-mexico","los-barriles-mexico","magdalena-bay-mexico","mahahual-mexico","mazamitla-mexico","merida-mexico","mexico-city-mexico","palenque-mexico","playa-del-carmen-mexico","puerto-aventuras-mexico","puerto-morelos-mexico","puerto-vallarta-mexico","punta-mita-mexico","rio-lagartos-mexico","san-cristobal-de-las-casas-mexico","san-jose-del-cabo-mexico","san-miguel-de-allende-mexico","san-sebastian-del-oeste-mexico","sayulita-mexico","sian-kaan-mexico","teotihuacan-mexico","tlaquepaque-mexico","todos-santos-mexico","tulum-mexico","uxmal-mexico","valladolid-mexico","valle-de-guadalupe-mexico"]}'::jsonb, 48),
  ('iguazu-falls-argentina', '10S', 'Iguazú Falls (Argentine Side)', 'Argentina', 'Iguazú Falls (Argentine Side)', 'live', 'verified', 'mountainValley', 'Northwest, Mendoza Wine & Iguazú', '{"expedition","culture"}', '{}', '{"essential","comfort","luxury","ultra"}', null, null, '{"key_facts":null,"safety":{"emergency":"911","emergency_secondary":["101 police","107 ambulance (SAME)","100 fire","0800 999 5000 tourist line"],"book_enabled":true,"air_access_verified":true,"air_access_note":"Puerto Iguazu / Cataratas del Iguazu Intl (IGR) via Buenos Aires AEP (domestic) / EZE (international); daily nonstops on Aerolineas Argentinas / Flybondi / JetSmart; IGR<->AEP among busiest domestic routes","trauma_note":"Puerto Iguazu hospital stabilises; serious trauma evac to Buenos Aires by air (IGR->AEP/EZE)","falls_footing":"catwalks + circuit boardwalks/stairs permanently misted & slippery; Lower Circuit most stair-heavy; Throat catwalk can close on river surge","gran_aventura_boat":"mandatory life jacket + briefing + dry-bags; jacket-quality reviews mixed; total soaking; river-level-dependent","triple_frontier_note":"Argentina-Brazil-Paraguay convergence is a transnational-crime region; avoid the Paraguay/Ciudad del Este side casually; park + Puerto Iguazu core safe with standard precautions; cross to Brazil before nightfall","health":"Misiones = CDC yellow-fever recommended + dengue risk; DEET, dawn/dusk cover, pre-travel vaccination consult","wildlife":"coatis bold near viewpoints — do NOT feed (bite/scratch)","mandatory_insurance":"Non-resident travel medical insurance required since 2025-07-01 (hospitalisation, repatriation, evacuation)","fcdo":{"posture":"1","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/argentina","read":"2026-08-20T14:54:24Z","page_updated":"2026-05-07T17:26:11+01:00","source_country":"argentina","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely"},"timing":{"peak_experience":"Mar-Apr & Aug-Sep (best flow-weather-crowd balance)","peak_flow_and_crowds":"Dec-Feb (max water flow, heat >35C, peak crowds); Easter week (Apr) crowd spike","shoulder_sleeper":"May (autumn flow, 30-40% lower rates)","quietest_days":"Tue-Thu","full_moon_walk":"5 nights/month only — plan around lunar calendar; 3 nightly departures, ~2.5 hr","fire_date":"curve-start minus 1-2 weeks; ~2 weeks before visible curve for a standard trip, but 6-12 months ahead for Awasi Iguazu or an in-park Gran Melia falls-view room"},"jewels":[{"name":"Garganta del Diablo catwalk (Devil''s Throat)","si_tag":"expedition","tier":"essential","source":"https://iguazufalls-tickets.org/what-to-see/devils-throat-iguazu-falls/","hook":"the marquee: 1.1 km of steel walkway out over the U-shaped canyon where 14 falls drop 82 m into permanent mist","si":"expedition","blurb":"the marquee: 1.1 km of steel walkway out over the U-shaped canyon where 14 falls drop 82 m into permanent mist","commission":"park-fee entry (non-commissionable) + DMC land package / activity affiliate framing","wells":["activities"],"wells_basis":"pass 2 — text","si_all":["expedition"],"shelf_fit":{"culture":"destination","expedition":"primary"},"commission_lane":["DMC","package","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Upper Circuit","si_tag":"expedition","tier":"essential","source":"https://iguazufalls.com/travel-guide/the-circuits-in-iguazu-falls/","hook":"~1.75 km, mostly flat, top-down panoramas across the cataract chain; the accessible headline alongside the Throat catwalk","si":"expedition","blurb":"~1.75 km, mostly flat, top-down panoramas across the cataract chain; the accessible headline alongside the Throat catwalk","commission":"park-fee + DMC/affiliate","wells":["activities"],"wells_basis":"pass 2 — text","si_all":["expedition"],"shelf_fit":{"culture":"destination","expedition":"primary"},"commission_lane":["DMC","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Lower Circuit + Isla San Martín boat","si_tag":"expedition","tier":"essential","source":"https://iguazutickets.com/guides/what-to-see-at-iguazu-falls/","hook":"~1.7 km, stairs down to the base, closest in-your-face angle, plus the passenger boat to the rocky Isla San Martín and its beach","si":"expedition","blurb":"~1.7 km, stairs down to the base, closest in-your-face angle, plus the passenger boat to the rocky Isla San Martín and its beach","commission":"park-fee + DMC/affiliate","wells":["activities","move"],"wells_basis":"pass 2 — text","si_all":["expedition"],"shelf_fit":{"culture":"destination","expedition":"primary"},"commission_lane":["DMC","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Gran Aventura — under-the-falls boat + 4x4","si_tag":"expedition","tier":"comfort","source":"https://iguazufalls.com/tours-and-activities/gran-aventura-activity/","hook":"the adrenaline jewel: 4×4 jungle trail to Puerto Macuco, then a 6 km semi-rigid run into the San Martín falls \"baptism of the mists.\"","si":"expedition","blurb":"the adrenaline jewel: 4×4 jungle trail to Puerto Macuco, then a 6 km semi-rigid run into the San Martín falls \"baptism of the mists.\"","commission":"in-park concession (largely non-commissionable) — package via DMC / frame via activity affiliate","wells":["move"],"wells_basis":"pass 2 — text","si_all":["expedition"],"shelf_fit":{"culture":"destination","expedition":"primary"},"commission_lane":["DMC","package","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Full-Moon Walk (Paseos de Luna Llena)","si_tag":"expedition","tier":"comfort","source":"https://iguazufalls.com/tours-and-activities/full-moon-walk-tour/","hook":"5 nights a month only, timed to the full moon: welcome drink + Guaraní music, Eco-Train through the night jungle to the Throat catwalk","si":"expedition","blurb":"5 nights a month only, timed to the full moon: welcome drink + Guaraní music, Eco-Train through the night jungle to the Throat catwalk","commission":"guided-only ticket via activity affiliate + DMC","wells":["stay","move","activities"],"wells_basis":"derived from name/blurb/hook","si_all":["expedition"],"shelf_fit":{"culture":"destination","expedition":"primary"},"commission_lane":["DMC","affiliate","guide"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Sunrise with in-park hotel (Gran Meliá privilege)","si_tag":"GEA/RHN","tier":"ultra","source":"https://www.jacadatravel.com/latin-america/argentina/iguazu-falls/accommodation/melia-iguazu/","si":"expedition","commission":"in-park hotel booking (ultra lane)","wells":["stay"],"wells_basis":"derived from name/blurb/hook","si_all":["GEA/RHN","expedition","romance"],"shelf_fit":{"GEA/RHN":"evidenced","culture":"destination","expedition":"primary","romance":"evidenced"},"commission_lane":["hotel"],"commission_embedded":false,"commission_basis":"lane","si_raw":"GEA/RHN","si_map_basis":"normalised from free text ''GEA/RHN'' by gen_normalise_jewel_si"},{"name":"Macuco jungle trail","si_tag":"expedition","tier":"essential","source":"http://www.iguazujungle.com/eng/web2/","hook":"the park''s longer forest walk to a hidden waterfall; coatis, toucans, capuchins, butterflies","si":"expedition","blurb":"the park''s longer forest walk to a hidden waterfall; coatis, toucans, capuchins, butterflies","commission":"self-guided or guided via in-park operator + DMC","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["expedition"],"shelf_fit":{"culture":"destination","expedition":"primary"},"commission_lane":["operator","DMC","guide"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Güirá Oga wildlife refuge","si_tag":"expedition","tier":"essential","source":"https://www.welcomeargentina.com/puertoiguazu/lodge-awasi-iguazu_i.html","hook":"\"bird house\" in Guaraní; a rescue-and-rehab centre for trafficked/injured native fauna just outside Puerto Iguazú","si":"expedition","blurb":"\"bird house\" in Guaraní; a rescue-and-rehab centre for trafficked/injured native fauna just outside Puerto Iguazú","commission":"activity affiliate + DMC add-on","wells":["stay"],"wells_basis":"pass 2 — text","si_all":["expedition"],"shelf_fit":{"culture":"destination","expedition":"primary"},"commission_lane":["DMC","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Brazilian-side panorama day-trip","si_tag":"culture","tier":"comfort","source":"https://sayhueque.com/our-trips/iguazu-falls/","hook":"cross to Parque Nacional do Iguaçu for the whole-system framed view Argentina can''t give you; passport-required border crossing, ~3–4 hr","si":"culture","blurb":"cross to Parque Nacional do Iguaçu for the whole-system framed view Argentina can''t give you; passport-required border crossing, ~3–4 hr","commission":"DMC/guided transfer + activity affiliate (cross-ref Brazil-side dossier)","wells":["move"],"wells_basis":"pass 2 — text","si_all":["culture"],"shelf_fit":{"culture":"primary","expedition":"destination"},"commission_lane":["DMC","affiliate","guide"],"commission_embedded":false,"commission_basis":"lane"},{"name":"San Ignacio Miní (UNESCO Jesuit-Guaraní mission)","si_tag":"culture","tier":"essential","source":"https://whc.unesco.org/en/list/275/","hook":"the roofless red-sandstone cathedral of a 1610 Jesuit reduction, UNESCO-listed 1984, ~300 km south toward Posadas","si":"culture","blurb":"the roofless red-sandstone cathedral of a 1610 Jesuit reduction, UNESCO-listed 1984, ~300 km south toward Posadas","commission":"DMC / guided excursion + activity affiliate","wells":["activities"],"wells_basis":"pass 2 — text","si_all":["culture"],"shelf_fit":{"culture":"primary","expedition":"destination"},"commission_lane":["DMC","affiliate","guide"],"commission_embedded":false,"commission_basis":"lane"}],"faq":[{"q":"What''s the best plan for a day at Iguazú Falls?","a":"Run the Devil''s Throat first at the 08:00 park opening, then work back through the Upper and Lower Circuits. The park opens 08:00 and closes 18:00 with last falls access around 16:30, and starting at the Garganta station gives the best rainbow light and thinnest crowds; budget 5–6 hours minimum for all three circuits plus the Eco-Train.","source":"iguazufalls-tickets.org, Accessed 2026-07-07","si_tag":"expedition"},{"q":"When is the best time to visit Iguazú Falls?","a":"March–April and August–September are the sweet spot, because they balance strong water flow with comfortable 20–30 °C temperatures and manageable crowds. December–February brings maximum flow but heat above 35 °C and peak crowds, while May is a quiet sleeper month with autumn flow and room rates 30–40% below the Dec–Feb peak.","source":"iguazutickets.com, Accessed 2026-07-07","si_tag":"expedition"},{"q":"Where should honeymooners stay at Iguazú?","a":"The two scarce in-jewel beds are the play: Awasi Iguazú (Relais & Châteaux, 14 stilted villas with a private guide and 4×4 each) and the Gran Meliá Iguazú, the only hotel inside the Argentine park. Both are near-zero on bedbanks and contract direct or via DMC, so book Awasi or an in-park falls-view room 6–12 months ahead.","source":"relaischateaux.com, Accessed 2026-07-07","si_tag":"romance"},{"q":"Should I visit the Brazilian side too — and what else is nearby?","a":"Yes if time allows: Argentina holds ~80% of the falls and the immersion, while Brazil''s single panoramic boardwalk delivers the whole-system view as a passport-required border day-trip. South toward Posadas, the roofless red-sandstone cathedral of San Ignacio Miní (UNESCO-listed 1984) rounds out a cultural-heritage circuit.","source":"sayhueque.com, Accessed 2026-07-07","si_tag":"culture"},{"q":"What''s the real risk to plan for at Iguazú?","a":"Health and weather, not crime. Misiones province carries a CDC yellow-fever vaccination recommendation and a real dengue risk, so pack DEET and get a pre-travel vaccination consult; the catwalks are permanently misted and slippery, and extreme rainfall can close the Devil''s Throat catwalk on river surge.","source":"wwwnc.cdc.gov, Accessed 2026-07-07","si_tag":"safety"},{"q":"Is the Gran Aventura speedboat dangerous?","a":"It is operator-run and low-risk with the rules followed, but not trivial. A life jacket is mandatory and a safety briefing is given before the 6 km run into the San Martín falls; jacket-quality reviews are mixed, so non-swimmers should weigh the run, everyone gets thoroughly soaked, and the trip is river-level-dependent and cancels in high water.","source":"iguazufalls.com, Accessed 2026-07-07","si_tag":"safety"}],"seo":{"meta_title":"Iguazú Falls, Argentine Side: Devil''s Throat, the Circuits & Gran Aventura Boat | TravelWell.World","meta_description":"Stand over the Devil''s Throat, walk the Upper and Lower Circuits, run the Gran Aventura boat under the falls, and stay inside the national park — the complete guide to the Argentine side of Iguazú.","search_language":"es-AR","local_keywords":["Cataratas del Iguazú","Garganta del Diablo","Gran Aventura Iguazú","circuito superior e inferior Iguazú","Tren Ecológico de la Selva","paseo de luna llena Cataratas","San Ignacio Miní ruinas","qué hacer en Puerto Iguazú"],"hreflang":["en","es-AR"],"jsonld_type":"TouristDestination","primary_keyword":"Iguazú Falls (Argentine Side)","attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-08-20","last_verified_basis":"safety.fcdo.read","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/argentina","read":"2026-08-20T14:54:24Z","source_updated":"2026-05-07T17:26:11+01:00"}]},"content_freshness":"2026-07-07","long_tail":["iguazu falls argentine side guide","garganta del diablo devil''s throat iguazu","iguazu upper and lower circuits","gran aventura boat ride iguazu","iguazu falls full moon walk","best time to visit iguazu falls","gran melia iguazu in-park hotel","awasi iguazu relais chateaux","iguazu argentina vs brazil side","san ignacio mini jesuit ruins"]},"booking":{"advisory_updated":"2026-08-20","advisory_authority":"FCDO"},"si_checklist_25":null,"sis_present":[{"si":"expedition","status":"live"},{"si":"culture","status":"live"}],"ultra":[{"name":"Awasi Iguazu","type":"Relais & Chateaux all-inclusive villa lodge","location":"Misiones jungle, ~20 min from falls","earning":"Virtuoso/Fora advisor commission + amenities","mor":"AOR/advisor","tier":"ultra"},{"name":"Gran Melia Iguazu","type":"in-park hotel (only one, Argentine side)","location":"inside Iguazu National Park","earning":"advisor/DMC commission + RedLevel upsell","mor":"AOR/advisor/DMC","tier":"ultra"},{"name":"Loi Suites Iguazu","type":"upscale jungle-river resort","location":"Iryapu reserve, ~10 min from Puerto Iguazu","earning":"advisor/DMC commission","mor":"AOR/DMC","tier":"luxury"}],"source_verified":null,"hero":{"query":"Iguazú Falls (Argentine Side), Argentina"},"geo":{"lat":-25.6953,"lng":-54.4367},"orbit":[{"id":"mendoza-argentina","jewels":11,"si":["culinary","romance","expedition"]},{"id":"salta-argentina","jewels":10,"si":["culture","expedition","culinary","romance"]}],"orbit_country":["buenos-aires-argentina","el-calafate-argentina","peninsula-valdes-argentina"]}'::jsonb, 49),
  ('isla-contoy-mexico', '10S', 'Isla Contoy', 'Mexico', '*If it''s 200 people a day on an island', 'live', 'verified', 'oceanAerial', 'Quintana Roo (Cancún & Riviera Maya)', '{"expedition","ocean","wildlife"}', '{}', '{"comfort"}', 'comfort', null, '{"key_facts":["Uninhabited national park capped at 200 visitors/day, authorized tours only","UNESCO-recognized reserve, habitat for 173+ bird species (frigatebirds, pelicans)","Ixlaché reef marks the northern start of the world''s 2nd-largest barrier reef","Sea-turtle nesting May-October; ~30 km north of Isla Mujeres","Day-trip only (no lodging); ~7-8 hr tours from Cancún/Isla Mujeres marinas"],"safety":{"emergency":"911","hospital":"uninhabited - no on-island care; evac via Isla Mujeres to Cancún (Galenia/Hospiten - verify)","malaria":"none in QR tourist zones (verify); dengue precautions","yellow_fever":"none required","fcdo":{"posture":"AREA-RESTRICTED","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-08-20T14:49:02Z","page_updated":"2026-07-16T16:08:09+01:00","source_country":"mexico","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely","fcdo_zones":[{"name":"The city of Tijuana, in Baja California","lvl":3,"posture":"all-but-essential","except":["airside transit through Tijuana airport","the Cross Border Xpress bridge linking the airport across the border","federal toll road 1D and the Via Rápida through Tijuana to the border"]},{"name":"The city of Tecate in Baja California, including roads between Tijuana and Tecate","lvl":3,"posture":"all-but-essential"},{"name":"The state of Chihuahua","lvl":3,"posture":"all-but-essential","except":["the city of Chihuahua","the border crossing in Ciudad Juárez via federal toll road 45","federal toll road 45D between Chihuahua and Ciudad Juárez","the Copper Canyon rail route and the towns immediately on it, including Creel","the road from Creel via San Juanito to San Pedro","state highway 16 from San Pedro to Chihuahua"],"note":"The advisory also covers the areas south-west of road 45D."},{"name":"The state of Sinaloa","lvl":3,"posture":"all-but-essential","except":["the cities of Los Mochis and Mazatlán","road 32 between El Fuerte and Los Mochis","the 15D federal toll road running the length of the state","the Copper Canyon rail route to and from Los Mochis and El Fuerte, and the towns immediately on it"]},{"name":"The state of Tamaulipas","lvl":3,"posture":"all-but-essential","except":["the border crossing at Nuevo Laredo via federal toll road 85D from Monterrey","federal highways 80, 81 and 85 between Tampico, Ciudad Victoria and Magueyes","the area of Tamaulipas south of those highways"]},{"name":"The state of Zacatecas","lvl":3,"posture":"all-but-essential"},{"name":"In Guanajuato: the areas south-west of road 45D","lvl":3,"posture":"all-but-essential","note":"FCDO advises against all but essential travel to the areas south-west of road 45D. (San Miguel de Allende and Guanajuato City sit outside this area.)"},{"name":"The state of Michoacán","lvl":3,"posture":"all-but-essential","except":["the city of Morelia via federal toll roads 15D, 126 and 43","toll road 48D between Morelia and its airport","the town of Pátzcuaro via toll roads 14D and 15 from Morelia, and boat trips on Lake Pátzcuaro","Federal Highway 15D"]},{"name":"In Jalisco: the areas south and south-west of Lake Chapala to the Colima border","lvl":3,"posture":"all-but-essential","note":"Thirty-nine named municipalities, including Autlán de Navarro, Sayula, Tapalpa, Cocula and Villa Corona — the advisory lists each by name."},{"name":"In Jalisco: eleven northern municipalities","lvl":3,"posture":"all-but-essential","note":"Bolaños, Chimaltitán, Colotlán, Hostotipaquillo, Huejúcar, Huequilla el Alto, Mezquitic, San Martín de Bolaños, Santa María de los Ángeles, Totatiche and Villa Guerrero."},{"name":"The state of Colima","lvl":3,"posture":"all-but-essential","except":["the city of Manzanillo by sea, or by air via Manzanillo-Costalegre International Airport","direct travel via road 200 from that airport to Manzanillo"]},{"name":"The state of Guerrero, including the city of Acapulco","lvl":3,"posture":"all-but-essential","except":["the town of Zihuatanejo/Ixtapa accessed by air"]},{"name":"Within 40km of the Guatemalan border, from the Pacific Coast up to and including the Gracias a Dios crossing","lvl":3,"posture":"all-but-essential"},{"name":"Federal Highway 199 between Rancho Nuevo, outside San Cristóbal de las Casas, and the Chancalá junction outside Palenque","lvl":3,"posture":"all-but-essential","note":"The restriction is the highway segment, not the towns at either end."}],"fcdo_zones_provenance":{"file":"src/data/safety.json","ref":"f8666636bc25790e0c9643ad5656f8d9fea37bf6","ref_committed":"2026-08-30T05:44:55Z","country_iso2":"MX","summary":"The FCDO advises against all but essential travel to named states, cities and border areas of Mexico — listed below in its own words, each with its own exceptions. The Yucatán Peninsula, Mexico City, Baja California Sur and the other main visitor regions carry no FCDO restriction.","source":"UK FCDO — Mexico travel advice, reviewed 2026-07-16 (verbatim snapshot from the research library)","_rule":"the FCDO restricted-area records for this country, verbatim. PRESENCE OF THIS BLOCK IS NOT A CLAIM THAT THIS DESTINATION SITS IN ANY OF THEM — membership is a coverage judgement and is set only in `zone_record`, by a human."}},"timing":{"peak":"Dec-Apr (dry, calm seas, best Ixlaché clarity) + Jun-Sep whale-shark corridor (sold as whale-shark + Contoy combos = true event peak)","shoulder":"May-Jun & Nov (easier permit-day availability; May-Jun straddles whale-shark open + turtle-nesting start)","green":"Jun-mid-Oct (hurricane season; exposed ~30 km open-water crossing - trips cancel in rough seas; disclose cancellation policy)","booking_lead":"200/day cap + authorized-only = book 3-6+ wks in peak (combos sell out with summer 30-39-day window), 1-3 wks shoulder; popular operators + calm-sea Sundays fill first","off_season_specials":"no beds - ''fill-the-permit-days'': green/shoulder = calm-day nature escape (birds + Ixlaché) bundled with off-island Isla Mujeres/Cancún stay","event_peaks":"Christmas-NY + spring break (Dec-Apr); sea-turtle nesting (May-Oct) + whale-shark run (Jun-Sep) are the island''s wildlife event peaks","fire_date":"whale-shark + Contoy combo Mar-Apr (6-8 wks pre-open); dry-season Ixlaché day-trip Aug-Sep; always pair with off-island stay CTA"},"jewels":[{"name":"Contoy authorized eco-expedition (200/day cap)","si_tag":"Global Expedition Adventures","status":"live","tier":"comfort","hook":"permitted boat + guided trail through frigatebird/pelican colonies","bookable_category":"authorized eco day tour","source":"https://contoyadventures.com/isla-contoy/","timing":"Dec-Apr  + Jun-Sep whale-shark corridor","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"expedition","blurb":"permitted boat + guided trail through frigatebird/pelican colonies","when":"Dec-Apr  + Jun-Sep whale-shark corridor","commission":"authorized operator → DMC/curated (park fee pass-through)","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["expedition","ocean"],"shelf_fit":{"expedition":"primary","ocean":"evidenced","wildlife":"destination"},"commission_lane":["operator","DMC"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Ixlaché reef snorkel","si_tag":"Ocean Adventures","status":"future","tier":"comfort","hook":"northern start of world''s 2nd-largest barrier reef, 17 hard + 14 soft corals","bookable_category":"snorkel stop within Contoy tour","source":"https://contoyadventures.com/isla-contoy/","timing":"Dec-Apr  + Jun-Sep whale-shark corridor","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"ocean","blurb":"northern start of world''s 2nd-largest barrier reef, 17 hard + 14 soft corals","when":"Dec-Apr  + Jun-Sep whale-shark corridor","commission":"authorized operator → curated (bundled)","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["ocean"],"shelf_fit":{"expedition":"destination","ocean":"primary","wildlife":"destination"},"commission_lane":["operator","bundle"],"commission_embedded":false,"commission_basis":"lane"},{"name":"173+ bird species + sea-turtle nesting","si_tag":"Wildlife & Nature","status":"future","tier":"comfort","hook":"frigatebirds, pelicans, green/loggerhead nesting beaches (May-Oct)","bookable_category":"guided nature walk (within tour)","source":"https://nationalparksassociation.org/mexico-national-parks/isla-contoy-national-park/","si":"wildlife","blurb":"frigatebirds, pelicans, green/loggerhead nesting beaches (May-Oct)","commission":"authorized operator → curated (conservation fee non-commissionable)","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["wildlife"],"shelf_fit":{"expedition":"destination","ocean":"destination","wildlife":"primary"},"commission_lane":["operator"],"commission_embedded":false,"commission_basis":"lane"}],"faq":[{"q":"What''s the real risk to plan for on an Isla Contoy trip?","a":"The open-water crossing and weather — not crime. Contoy sits ~30 km out at the seam where the Caribbean meets the Gulf, an exposed run where sea state can build and operators cancel trips in rough weather (especially hurricane season, Jun–Nov). Pick a calm-sea day, confirm the cancellation/reschedule policy, and keep life jackets on during transit.","source":"airial.travel, 2026-07-04","si_tag":"safety"},{"q":"Is the reef snorkel and boat crossing dangerous?","a":"Both are low-risk with a guide, but respect the water. Snorkeling is snorkel-only with no decompression restriction — the real hazards are the open-water current at the reef seam, boat traffic and sun, so wear the vest, avoid all coral/wildlife contact and stay with the guide. On the ~30 km crossing, follow crew instructions and keep life jackets on.","source":"nationalparksassociation.org, 2026-07-04","si_tag":"safety"},{"q":"How do you actually visit Isla Contoy?","a":"Only through a handful of authorized operators — there is no independent access. The daily cap of 200 visitors makes it scarcity-priced, so book 3–6+ weeks ahead in peak season (1–3 weeks in shoulder); popular operators and calm-sea days fill first. Every trip bundles the park fee, lunch and snorkel gear.","source":"contoyadventures.com / airial.travel, 2026-07-04","si_tag":"expedition"},{"q":"What is the Ixlaché reef snorkel like?","a":"It is the headline in-water stop — the northern start of the world''s second-largest barrier reef. Ixlaché holds 17 hard and 14 soft coral species just south of the island; visibility is clearest in the dry season (Dec–Apr), and the snorkel is included in the guided tour on calm-sea days.","source":"contoyadventures.com, 2026-07-04","si_tag":"ocean"},{"q":"What wildlife will I see on Isla Contoy?","a":"Birds above all — the island is critical habitat for 173+ species, with frigatebird and pelican colonies you pass on the marked trails. Green and loggerhead sea turtles nest on the beaches May–October, adding a seasonal wildlife hook; the whole reserve is car-free and strictly protected.","source":"nationalparksassociation.org, 2026-07-04","si_tag":"wildlife"},{"q":"When is the best time to visit Isla Contoy, and where do trips leave from?","a":"December–April brings the calmest seas and clearest Ixlaché water; the summer whale-shark run (roughly Jun–Sep) is the true event peak, since Contoy is often sold as a whale-shark + Contoy combo. Trips depart Cancún and Isla Mujeres marinas on ~7–8 hour days — there is no lodging, so base off-island.","source":"isla-seatours.com / machupicchu.org, 2026-07-04","si_tag":"planning"}],"seo":{"meta_title":"Isla Contoy, Mexico: 200-a-Day National Park Island","meta_description":"Uninhabited and capped at 200 visitors a day — Isla Contoy''s bird sanctuary and Ixlaché reef are authorized-tour-only. How to book the trip and what to expect.","slug":"isla-contoy-mexico","primary_keyword":"Isla Contoy national park tour","long_tail":["Isla Contoy 200 visitors per day","Ixlaché reef snorkeling","Isla Contoy bird sanctuary","Isla Contoy day trip from Cancún","Isla Contoy authorized operators"],"search_language":"es-MX (restated, not machine-translated)","local_keywords":["tour a Isla Contoy","Parque Nacional Isla Contoy","snorkel arrecife Ixlaché","santuario de aves Isla Contoy","excursión Isla Contoy desde Cancún","operadores autorizados Isla Contoy","combo tiburón ballena e Isla Contoy"],"hreflang":["en","es-MX"],"jsonld_type":"TouristAttraction","content_freshness":"2026-07-04","attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-07-04","last_verified_basis":"source_verified","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-08-20T14:49:02Z","source_updated":"2026-07-16T16:08:09+01:00"}]}},"booking":{"advisory_updated":"2026-08-20","advisory_authority":"FCDO"},"si_checklist_25":null,"sis_present":[{"si":"expedition","status":"live"},{"si":"ocean","status":"future"},{"si":"wildlife","status":"future"}],"ultra":[{"name":"NONE - uninhabited national park, no lodging","why_ultra":"Isla Contoy is an uninhabited national park: no hotels/villas/lodging, no overnight permitted - day-trip add-on, not a stay. Ultra play lives off-island (Isla Mujeres Impression / Cancún Nizuc / Mayakoba corridor - verify municipality)","earning":"n/a on-island; on application via associated Isla Mujeres/Puerto Morelos dossiers","virtuoso_value_add":"n/a on-island - see associated dossiers","mor":"no on-island revenue; commission captured on associated stay + day-tour","source":"https://nationalparksassociation.org/mexico-national-parks/isla-contoy-national-park/"}],"source_verified":"2026-07-04","hero":{"query":"Isla Contoy, Mexico"},"geo":{"lat":21.4833,"lng":-86.7917},"orbit":[{"id":"akumal-mexico","jewels":5,"si":["diveglobal","ocean","culture"]},{"id":"bacalar-mexico","jewels":6,"si":["tropical","wellness","adventure"]},{"id":"cancun-mexico","jewels":5,"si":["tropical","adventure","diveglobal","ocean"]},{"id":"coba-mexico","jewels":5,"si":["culture","expedition","family"]},{"id":"cozumel-mexico","jewels":5,"si":["diveglobal","liveaboard","ocean"]},{"id":"holbox-mexico","jewels":4,"si":["expedition","romance","ocean","wildlife"]},{"id":"isla-mujeres-mexico","jewels":5,"si":["tropical","ocean","diveglobal","adventure"]},{"id":"mahahual-mexico","jewels":5,"si":["liveaboard","diveglobal"]},{"id":"playa-del-carmen-mexico","jewels":5,"si":["romance","expedition","diveglobal","culture"]},{"id":"puerto-aventuras-mexico","jewels":5,"si":["romance","diveglobal","ocean","wildlife"]},{"id":"puerto-morelos-mexico","jewels":5,"si":["diveglobal","ocean","adventure","culinary"]},{"id":"sian-kaan-mexico","jewels":5,"si":["expedition","wildlife","tropical"]},{"id":"tulum-mexico","jewels":5,"si":["expedition","diveglobal","culture","wildlife"]}],"orbit_country":["balandra-beach-mexico","cabo-pulmo-mexico","cabo-san-lucas-mexico","calakmul-mexico","campeche-city-mexico","careyes-mexico","celestun-mexico","chapala-ajijic-mexico","chichen-itza-mexico","costalegre-mexico","east-cape-mexico","ensenada-mexico","espiritu-santo-island-mexico","guadalajara-mexico","guanajuato-city-mexico","huatulco-mexico","izamal-mexico","la-paz-mexico","loreto-mexico","los-barriles-mexico","magdalena-bay-mexico","mazamitla-mexico","merida-mexico","mexico-city-mexico","oaxaca-city-mexico","palenque-mexico","puerto-vallarta-mexico","punta-mita-mexico","rio-lagartos-mexico","san-cristobal-de-las-casas-mexico","san-jose-del-cabo-mexico","san-miguel-de-allende-mexico","san-sebastian-del-oeste-mexico","sayulita-mexico","teotihuacan-mexico","tlaquepaque-mexico","todos-santos-mexico","uxmal-mexico","valladolid-mexico","valle-de-guadalupe-mexico","puerto-escondido-mexico"]}'::jsonb, 50),
