"posture":"all-but-essential","except":["the city of Manzanillo by sea, or by air via Manzanillo-Costalegre International Airport","direct travel via road 200 from that airport to Manzanillo"]},{"name":"The state of Guerrero, including the city of Acapulco","lvl":3,"posture":"all-but-essential","except":["the town of Zihuatanejo/Ixtapa accessed by air"]},{"name":"Within 40km of the Guatemalan border, from the Pacific Coast up to and including the Gracias a Dios crossing","lvl":3,"posture":"all-but-essential"},{"name":"Federal Highway 199 between Rancho Nuevo, outside San Cristóbal de las Casas, and the Chancalá junction outside Palenque","lvl":3,"posture":"all-but-essential","note":"The restriction is the highway segment, not the towns at either end."}],"fcdo_zones_provenance":{"file":"src/data/safety.json","ref":"f8666636bc25790e0c9643ad5656f8d9fea37bf6","ref_committed":"2026-08-30T05:44:55Z","country_iso2":"MX","summary":"The FCDO advises against all but essential travel to named states, cities and border areas of Mexico — listed below in its own words, each with its own exceptions. The Yucatán Peninsula, Mexico City, Baja California Sur and the other main visitor regions carry no FCDO restriction.","source":"UK FCDO — Mexico travel advice, reviewed 2026-07-16 (verbatim snapshot from the research library)","_rule":"the FCDO restricted-area records for this country, verbatim. PRESENCE OF THIS BLOCK IS NOT A CLAIM THAT THIS DESTINATION SITS IN ANY OF THEM — membership is a coverage judgement and is set only in `zone_record`, by a human."}},"timing":{"peak":"Dec-Apr (region dry/high season) + Jun-Sep whale-shark event peak (snorkel-only)","shoulder":"May-Jun & Nov (~30-40% off winter rates)","green":"Jun-mid-Oct (hurricane season, ~40-60% off; whale-shark peak sits inside it)","booking_lead":"whale-shark tours ~30-39 days (book 3-6 wks ahead, sells out summer); shoulder beds 2-4 wks; ultra/boutique suites Dec-Apr + holidays 3-6+ months","off_season_specials":"green-season play = discounted island bed + premium whale-shark excursion (''cheap bed, peak wildlife''); disclose hurricane/sargassum","event_peaks":"Christmas-New Year, US spring break (Mar); whale-shark open (early Jun) + Jul-Aug midsummer height","fire_date":"whale-shark Mar-Apr (6-8 wks pre-open); winter/honeymoon-suite Aug-Sep; green-season value Apr-May"},"jewels":[{"name":"Whale-shark snorkel departures","si_tag":"ocean","status":"future","tier":"comfort","hook":"island boats to the aggregation, Jun-Sept, snorkel-only","bookable_category":"boat snorkel excursion","source":"https://mexicodivers.com/","si":"ocean","blurb":"island boats to the aggregation, Jun-Sept, snorkel-only","commission":"DMC/local operator → OTA affiliate","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["diveglobal","ocean","tropical"],"shelf_fit":{"adventure":"destination","diveglobal":"evidenced","ocean":"primary","tropical":"evidenced"},"commission_lane":["operator","DMC","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"MUSA south wing","si_tag":"diveglobal","status":"future","tier":"comfort","hook":"shallow sculpture reef divable by beginners and snorkelers","bookable_category":"dive/snorkel tour","source":"https://www.bluewaterdivetravel.com/scuba-musa-isla-mujeres-cancun","timing":"Dec-Apr  + Jun-Sep whale-shark event peak","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"diveglobal","blurb":"shallow sculpture reef divable by beginners and snorkelers","when":"Dec-Apr  + Jun-Sep whale-shark event peak","commission":"local dive-op → OTA affiliate","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["diveglobal","tropical"],"shelf_fit":{"adventure":"destination","diveglobal":"primary","ocean":"destination","tropical":"evidenced"},"commission_lane":["operator","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Punta Sur loggerhead-turtle dive","si_tag":"diveglobal","status":"future","tier":"premier","hook":"summer mating aggregation in south-point current","bookable_category":"guided drift dive","source":"https://www.pocnadivecenter.com/post/scuba-diving-with-loggerheads-in-isla-mujeres","si":"diveglobal","blurb":"summer mating aggregation in south-point current","commission":"local dive-op (advanced) → curated-recommend","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["diveglobal"],"shelf_fit":{"adventure":"destination","diveglobal":"primary","ocean":"destination","tropical":"destination"},"commission_lane":["operator"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Playa Norte at dawn","si_tag":"tropical","status":"live","tier":"comfort","hook":"waist-deep glass-calm turquoise, sargassum-protected","bookable_category":"hotel + ferry","source":"https://www.howisthesargassum.com/blog/cancun-hurricane-season-2026","timing":"Dec-Apr  + Jun-Sep whale-shark event peak","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"tropical","blurb":"waist-deep glass-calm turquoise, sargassum-protected","when":"Dec-Apr  + Jun-Sep whale-shark event peak","commission":"bed-bank/boutique portal → OTA; ferry pass-through","wells":["stay","move"],"wells_basis":"derived from name/blurb/hook","si_all":["tropical"],"shelf_fit":{"adventure":"destination","diveglobal":"destination","ocean":"destination","tropical":"primary"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed"},{"name":"Isla Contoy day trip","si_tag":"globaladv","status":"future","tier":"comfort","hook":"200/day capped bird-sanctuary reserve + Ixlaché reef","bookable_category":"authorized eco day tour","source":"https://contoyadventures.com/isla-contoy/","timing":"Dec-Apr  + Jun-Sep whale-shark event peak","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"adventure","blurb":"200/day capped bird-sanctuary reserve + Ixlaché reef","when":"Dec-Apr  + Jun-Sep whale-shark event peak","commission":"authorized Contoy operator/DMC → curated (fee pass-through)","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["adventure","tropical"],"shelf_fit":{"adventure":"primary","diveglobal":"destination","ocean":"destination","tropical":"evidenced"},"commission_lane":["operator","DMC"],"commission_embedded":false,"commission_basis":"lane"}],"faq":[{"q":"What''s the real risk to plan for on Isla Mujeres?","a":"Water, weather and currents — not crime. Drink bottled water, use repellent for dengue (no malaria in the tourist zone), and note hurricane season runs June–November with September riskiest. Playa Norte is comparatively sargassum-protected, but 2026 is heavy region-wide; the Punta Sur loggerhead dives sit in strong currents, so they are for advanced divers only.","source":"howisthesargassum.com","si_tag":"safety"},{"q":"Is swimming with whale sharks or diving Punta Sur dangerous?","a":"The whale-shark encounter is snorkel-only with no decompression restriction — wear the vest, no touching, stay with the guide against boat traffic and open-water current. Punta Sur''s summer loggerhead dive is a strong-current drift for advanced divers with a local guide; observe no-fly of 18–24 hours after any scuba.","source":"pocnadivecenter.com","si_tag":"safety"},{"q":"When and how can I swim with whale sharks from Isla Mujeres?","a":"Roughly June to September, on a snorkel-only boat excursion to the aggregation — the island is the whale-shark snorkel capital of the region. Tours book about 30–39 days out on average and sell out fast in peak summer, so reserve at least 3–6 weeks ahead; it is snorkel-only, with no scuba allowed.","source":"mexicodivers.com","si_tag":"ocean"},{"q":"Can beginners dive MUSA from Isla Mujeres?","a":"Yes — MUSA is one of the most accessible dives anywhere. Its 470+ statues sit just 3.5–8 m down, shallow enough for Open Water divers and snorkelers, and at ≤9 m these are easy day dives. Advanced divers can add the Punta Sur loggerhead drift in summer, which sits in strong current and is guided-only.","source":"bluewaterdivetravel.com","si_tag":"diveglobal"},{"q":"Is Playa Norte good, and will sargassum ruin it?","a":"It is the island''s signature beach — waist-deep, glass-calm turquoise you can wade out a hundred meters into — and one of the most sargassum-protected stretches in the region. In a heavy year like 2026 that protection is a genuine edge, but still disclose: no beach is fully immune, and mornings are cleanest.","source":"howisthesargassum.com","si_tag":"tropical"}],"seo":{"meta_title":"Isla Mujeres, Mexico: Whale Sharks, MUSA & Playa Norte","meta_description":"A golf-cart island off Cancún — snorkel the whale-shark run, dive MUSA and Punta Sur loggerheads, and wade Playa Norte''s calm turquoise. Season, safety, booking.","slug":"isla-mujeres-mexico","primary_keyword":"Isla Mujeres whale shark snorkeling","long_tail":["Isla Mujeres MUSA diving","Playa Norte Isla Mujeres","Punta Sur loggerhead turtles","Isla Mujeres whale shark season","Isla Contoy tour from Isla Mujeres"],"search_language":"es-MX (restated, not machine-translated)","local_keywords":["nadar con tiburón ballena Isla Mujeres","buceo MUSA Cancún","Playa Norte Isla Mujeres","temporada de tiburón ballena","tortugas caguama Punta Sur","qué hacer en Isla Mujeres","villas de lujo Isla Mujeres"],"hreflang":["en","es-MX"],"jsonld_type":"TouristDestination","content_freshness":"2026-07-04","attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-07-04","last_verified_basis":"source_verified","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-08-20T14:49:02Z","source_updated":"2026-07-16T16:08:09+01:00"}]}},"booking":{"codes":[],"note":"MXN currency, USD widely accepted","advisory_updated":"2026-08-20","advisory_authority":"FCDO"},"si_checklist_25":{"run_date":"2026-07-31","hits":7,"misses":15,"disregarded":3,"note":"Canonical 25-SI list; sports limited to participant; spectator/prosports/compsports disregarded"},"sis_present":[{"si":"tropical","name":"tropical","status":"live"},{"si":"ocean","name":"ocean","status":"future"},{"si":"diveglobal","name":"diveglobal","status":"future"},{"si":"globaladv","name":"adventure","status":"future"}],"ultra":[{"name":"Impression Isla Mujeres by Secrets","why_ultra":"125 all-suite adults-only, butler + Endless Privileges, 8 restaurants, private catamaran transfer; ''Most Instagrammable Hotel in the World'' 2 yrs running — island''s true ultra flagship","earning":"on application / via host-Virtuoso (Hyatt Inclusive Collection); verify %","virtuoso_value_add":"verify Virtuoso/Hyatt Prive amenities - not documented","mor":"commission-on-net; no net-rate resale markup","source":"https://www.hyattinclusivecollection.com/en/resorts-hotels/impression-by-secrets/mexico/isla-mujeres/"},{"name":"Mia Reef Isla Mujeres (All-Inclusive)","why_ultra":"private-island feel at Playa Norte tip, dock-connected, 93 rooms + 63 suites, King''s Pool snorkel lagoon — upper-luxe marquee, not five-diamond (reviews flag dated facilities)","earning":"on application via host/OTA; verify","virtuoso_value_add":"verify - not documented","mor":"commission-on-net; no resale markup","source":"https://www.tripadvisor.com/Hotel_Review-g150810-d259074-Reviews-Mia_Reef_Isla_Mujeres-Isla_Mujeres_Yucatan_Peninsula.html"},{"name":"Nearest true ultra: Cancún Nizuc / Playa Mujeres / Mayakoba corridor (mainland)","why_ultra":"AAA Five-Diamond / Virtuoso-preferred ultra is mainland (Nizuc, Mayakoba Rosewood/Banyan Tree/Fairmont/