only in `zone_record`, by a human."}},"timing":{"inflection_curve_start":"2026-11-01","peak":"2026-12 to 2027-04","shoulder":"2026-05 to 2026-10 (hot/humid; hurricane exposure Aug-Oct; year-round photo baseline)","fire_date":"2026-10-20","trigger_rule":"curve-start minus 1-2 weeks; front-runs both dry-season inflection and Hanal Pixán; attaches to Mérida-base / in-town boutique lead time","booking_lead_days":{"day_tour":"2-7","in_town_boutique":"7-28","merida_base_high_season":"28-84"},"event_peaks":["Hanal Pixán / Día de Muertos 2026-10-31 to 2026-11-02 (headline)","year-round artisan & photo-travel demand","calesa demand steady all year"],"note":"sharpen on live tracking — Mérida occupancy + Izamal Pueblo-Mágico visitor counts + Hanal Pixán calendar"},"jewels":[{"name":"Convento de San Antonio de Padua (golden convent, sunset)","si_tag":"culture_heritage","source":"https://www.atlasobscura.com/places/yellow-city-of-izamal | Accessed 2026-07-06","si":"culture","commission":"non-commissionable entry; anchors tour + sunset-stay night","accessed":"2026-07-06","wells":["activities"],"wells_basis":"pass 2 — text","si_all":["culture"],"shelf_fit":{"culinary":"destination","culture":"primary","romance":"destination"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed"},{"name":"Kinich Kakmó pyramid (climbable)","si_tag":"culture_heritage","tier":"comfort","source":"https://tourtochichenitza.com/destinations/izamal | Accessed 2026-07-06","hook":"Unlike El Castillo at Chichén, Izamal''s Kinich Kakmó is climbable to the summit for rooftop views over the yellow city.]","si":"culture","blurb":"Unlike El Castillo at Chichén, Izamal''s Kinich Kakmó is climbable to the summit for rooftop views over the yellow city.]","commission":"day-tour inclusion (guiding); entry non-commissionable","accessed":"2026-07-06","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["culture"],"shelf_fit":{"culinary":"destination","culture":"primary","romance":"destination"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed"},{"name":"Pope John Paul II heritage (1993 visit, JP-II statue)","si_tag":"culture_heritage","tier":"comfort","source":"https://en.wikipedia.org/wiki/Izamal | Accessed 2026-07-06","si":"culture","commission":"guided-tour narrative anchor; faith-travel draw","accessed":"2026-07-06","wells":["activities"],"wells_basis":"pass 2 — text","si_all":["culture"],"shelf_fit":{"culinary":"destination","culture":"primary","romance":"destination"},"commission_lane":["guide"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Centro Cultural y Artesanal (folk-art museum + workshops)","si_tag":"culture_heritage","tier":"comfort","source":"https://themexicoreport.com/entrepreneurs-preserve-mayan-culture-and-traditions-at-centro-cultural-y-artesanal-in-izamal-yucatan/ | Accessed 2026-07-06","timing":"year-round","timing_type":"ALWAYS-ON","si":"culture","when":"year-round","commission":"experience add-on (affiliate/Viator); workshop packages","accessed":"2026-07-06","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["culture"],"shelf_fit":{"culinary":"destination","culture":"primary","romance":"destination"},"commission_lane":["package","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Sunset calesa (horse-carriage) ride","si_tag":"romance","tier":"comfort","source":"https://tourtochichenitza.com/destinations/izamal | Accessed 2026-07-06","hook":"low-speed, low-risk, but shared with light town traffic; standard care boarding/alighting. Guided calesa tours are the norm and low-hazard","si":"romance","blurb":"low-speed, low-risk, but shared with light town traffic; standard care boarding/alighting. Guided calesa tours are the norm and low-hazard","commission":"bookable experience add-on (Viator/GetYourGuide; Host for private)","accessed":"2026-07-06","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["romance"],"shelf_fit":{"culinary":"destination","culture":"destination","romance":"primary"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed"},{"name":"Golden-hour photo circuit (yellow arcades + convent)","si_tag":"romance","tier":"premier","source":"https://www.bontraveler.com/izamal-yucatan-mexico-yellow-city/ | Accessed 2026-07-06","si":"romance","commission":"private photo-tour upsell; drives one-night boutique room-night","accessed":"2026-07-06","wells":["activities"],"wells_basis":"pass 2 — text","si_all":["romance"],"shelf_fit":{"culinary":"destination","culture":"destination","romance":"primary"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed"},{"name":"Hammock & artisan workshops (huipil, alebrijes)","si_tag":"culinary","tier":"comfort","source":"https://yucatantoday.com/en/blog/yucatans-most-iconic-handcrafts-artisan-towns | Accessed 2026-07-06","si":"culinary","commission":"artisan-experience + retail add-on; Centro Cultural packages","accessed":"2026-07-06","wells":["activities","shop"],"wells_basis":"derived from name/blurb/hook","si_all":["culinary"],"shelf_fit":{"culinary":"primary","culture":"destination","romance":"destination"},"commission_lane":["package"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Santa Bárbara cenotes (nearby, ~49 km)","si_tag":"romance","tier":"comfort","source":"https://tourtochichenitza.com/destinations/izamal | Accessed 2026-07-06","si":"romance","commission":"adventure add-on (operator/Viator)","accessed":"2026-07-06","wells":[],"wells_basis":"text supports no Well — needs a human read","si_all":["romance"],"shelf_fit":{"culinary":"destination","culture":"destination","romance":"primary"},"commission_lane":["operator"],"commission_embedded":false,"commission_basis":"lane"}],"faq":[{"q":"Why is Izamal called the Yellow City, and what makes it special?","a":"It is Mexico''s first Pueblo Mágico (designated 2002), and the entire historic center is painted one standardized ochre-gold — a color tradition set for Pope John Paul II''s August 1993 visit and maintained ever since. The city is built in layers: the Spanish set the great Franciscan convent atop a Maya temple, and the Kinich Kakmó sun-god pyramid still rises above the rooftops.","source":"en.wikipedia.org / casaloltun.com, 2026-07-06","si_tag":"culture"},{"q":"Can you climb the pyramid in Izamal?","a":"Yes — Kinich Kakmó is climbable to the summit, which sets it apart from Chichén Itzá, where El Castillo has been closed to climbers since 2008. The ~200 × 180 m pyramid dates to c. 400–600 AD; the steps are steep, uneven Maya risers with no handrails, so wear sturdy shoes and mind your footing on the descent.","source":"tourtochichenitza.com, 2026-07-06","si_tag":"culture"},{"q":"Is Izamal good for a romantic day or honeymoon?","a":"Yes — it is a golden-hour romance magnet. The convent glows like a lantern above the plaza at sunset, a 45–60 min horse-drawn calesa ride winds through the yellow arcades, and the light seems to come from the buildings themselves. Most couples day-trip it from Mérida (70 km / ~1h10) or book one night in an in-town boutique to shoot the convent at golden hour.","source":"bontraveler.com, 2026-07-06","si_tag":"romance"},{"q":"What is there to do beyond the convent?","a":"Hands-on Maya craft: the Centro Cultural y Artesanal runs artisan workshops and tours to hammock weavers, huipil embroiderers and alebrije painters who often work in-shop while you eat. Yucatecan cuisine and Hanal Pixán (the Maya Day of the Dead food tradition) give a soft culinary layer for later.","source":"yucatantoday.com, 2026-07-06","si_tag":"culinary"},{"q":"What''s the real risk to plan for in Izamal?","a":"Heat and footing, not crime. The shadeless plazas and the exposed, handrail-free Kinich Kakmó climb get hot at midday, so carry water, a hat and sunscreen and shoot golden hour rather than noon. Izamal has local clinics only — the nearest full trauma care is Mérida, ~1h10 west.","source":"https://www.gov.uk/foreign-travel-advice/mexico","si_tag":"safety"}],"seo":{"jsonld_type":"TouristAttraction","meta_title":"Izamal, the Yellow City: Pueblo Mágico Guide (2026) | TravelWell.World","search_language":"en","local_keywords":["Izamal ciudad amarilla","Convento Izamal","Convento de San Antonio de Padua","pirámide Kinich Kakmó","calesa Izamal","Pueblo Mágico Izamal","artesanías Izamal"],"hreflang":["en","es-MX"],"content_freshness":"2026-07-06","attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-07-06","last_verified_basis":"source_verified","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-08-20T14:49:02Z","source_updated":"2026-07-16T16:08:09+01:00"}]},"long_tail":["Izamal yellow city guide 2026","Izamal from Mérida day trip","Convento San Antonio de Padua Izamal","Kinich Kakmó pyramid climb","Izamal calesa horse carriage ride","Izamal sunset photography"]},"booking":{"advisory_updated":"2026-08-20","advisory_authority":"FCDO"},"si_checklist_25":null,"sis_present":["culture_heritage","romance","culinary"],"ultra":[{"name":"Hotel San Miguel Arcángel (in-town)","tier":"premier_boutique","earning_path":"Host FIT / MoR","note":"ceiling in-town; no true ultra hotel in Izamal itself","source":"https://yucatantoday.com/en/izamal/ | Accessed 2026-07-06"},{"name":"Chablé Yucatán","tier":"ultra","earning_path":"Virtuoso / Fora","note":"nearest ultra; ~30 min Mérida; #13 World''s Best Hotels 2023","source":"https://www.virtuoso.com/travel/luxury-hotels/15452675/chable-yucatan | Accessed 2026-07-06"},{"name":"Hacienda Temozón (Luxury Collection)","tier":"ultra","earning_path":"Virtuoso / Marriott STARS / Fora / MoR","note":"28-room grand hacienda","source":"https://www.travelweekly.com/Hotels/Abala-Mexico/Hacienda-Temozon-Luxury-Collection-p51093491 | Accessed 2026-07-06"},{"name":"Hacienda Santa Rosa (Luxury Collection)","tier":"ultra","earning_path":"Virtuoso / Marriott STARS / MoR","note":"intimate 11 rooms","source":"https://www.letstraveltomexico.com/yucatan-haciendas/ | Accessed 2026-07-06"}],"source_verified":"2026-07-06","hero":{"query":"Izamal, Mexico"},"geo":{"lat":20.9308,"lng":-89.0175},"orbit":[{"id":"celestun-mexico","jewels":6,"si":["expedition","tropical"]},{"id":"chichen-itza-mexico","jewels":7,"si":["culture","expedition","wellness"]},{"id":"merida-mexico","jewels":15,"si":["romance","expedition","culture","culinary"]},{"id":"rio-lagartos-mexico","jewels":6,"si":["expedition","tropical"]},{"id":"uxmal-mexico","jewels":11,"si":["culture","expedition","culinary"]},{"id":"valladolid-mexico","jewels":9,"si":["expedition","culture","culinary"]}],"orbit_country":["akumal-mexico","bacalar-mexico","balandra-beach-mexico","cabo-pulmo-mexico","cabo-san-lucas-mexico","calakmul-mexico","campeche-city-mexico","cancun-mexico","careyes-mexico","chapala-ajijic-mexico","coba-mexico","costalegre-mexico","cozumel-mexico","east-cape-mexico","ensenada-mexico","espiritu-santo-island-mexico","guadalajara-mexico","guanajuato-city-mexico","holbox-mexico","huatulco-mexico","isla-contoy-mexico","isla-mujeres-mexico","la-paz-mexico","loreto-mexico","los-barriles-mexico","magdalena-bay-mexico","mahahual-mexico","mazamitla-mexico","mexico-city-mexico","oaxaca-city-mexico","palenque-mexico","playa-del-carmen-mexico","puerto-aventuras-mexico","puerto-morelos-mexico","puerto-vallarta-mexico","punta-mita-mexico","san-cristobal-de-las-casas-mexico","san-jose-del-cabo-mexico","san-miguel-de-allende-mexico","san-sebastian-del-oeste-mexico","sayulita-mexico","sian-kaan-mexico","teotihua