  ('jericoacoara-brazil', '10S', 'Jericoacoara & the Ceará Coast, Brazil', 'Brazil', 'Jericoacoara & the Ceará Coast', 'live', 'verified', 'tropicalBeach', 'Northeast Beaches & Bahia', '{"tropical","romance"}', '{"tropical"}', '{"essential","comfort","premier"}', null, null, '{"key_facts":null,"safety":{"emergency":"190","book_enabled":true,"air_access_verified":true,"air_access":["JJD (Jericoacoara Airport, ~35 min transfer)","FOR (Fortaleza/Pinto Martins) + 4-5 hr authorized 4x4 dune transfer (~300 km)"],"remote_flag":true,"trauma_note":"Remote, road-less; definitive care/evac via Fortaleza then US air evac; factor 4x4-only ground leg; med-evac insurance advised","water_hazards":["riptides/strong currents","shorebreak","strong-wind open-water kite hazard"],"environmental":["high UV / sun exposure","dune heat","minimal shade"],"fcdo":{"posture":"AREA-RESTRICTED","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/brazil","read":"2026-08-20T14:54:23Z","page_updated":"2026-05-11T12:32:48+01:00","source_country":"brazil","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely","fcdo_zones":[{"name":"River areas in the west of Amazonas State","lvl":3,"posture":"all-but-essential","note":"Along the Amazon River and its tributaries west of Codajás and east of Belém do Solimões; any part of the Itaquaí River; any part of the Japurá River or its tributaries; and the Rio Negro and its tributaries north or west of Barcelos."}],"fcdo_zones_provenance":{"file":"src/data/safety.json","ref":"f8666636bc25790e0c9643ad5656f8d9fea37bf6","ref_committed":"2026-08-30T05:44:55Z","country_iso2":"BR","summary":"The FCDO advises against all but essential travel to river areas in the west of Amazonas State — listed below in its own words. The rest of Brazil, including Salvador, Rio de Janeiro and the coastal cities, carries no FCDO restriction.","source":"UK FCDO — Brazil travel advice, reviewed 2026-05-11 (ve