  ('la-paz-mexico', '10S', 'La Paz', 'Mexico', 'La Paz whale sharks', 'live', 'verified', 'oceanAerial', 'Baja California Sur (Los Cabos & La Paz)', '{"expedition","tropical","diveglobal"}', '{"tropical"}', '{"essential","comfort","premier"}', null, null, '{"key_facts":["Whale-shark season Oct 1-Apr 30 in bay refuge zone; juveniles 4-8m; snorkel-only, 5 pax + guide per shark, 30-min limit, licensed operators","Los Islotes: 600+ California sea lions, ~1hr by boat; snorkel-only; colony closed Jun 1-Aug 31 (pupping)","Espiritu Santo: UNESCO World Heritage (2005) + Archipielago Espiritu Santo National Park (2007); CONANP paper-bracelet permit required","La Paz is the DMC/lodging hub and launch port for Espiritu Santo and the whale-shark bay","Hyperbaric chamber present in La Paz; Salvatierra ferry wreck dive at 18-20m"],"safety":{"emergency":"911","hospital":"Hospital General Juan Maria Salvatierra (public, 2nd-level) + ISSSTE Hospital General La Paz; private clinics + air-evac for major trauma; carry medical/evac insurance","malaria":"effectively none in Baja California Sur","dengue":"circulates in Mexico - use repellent","water":"bottled/purified only","hurricane":"Jun-Nov - carry trip insurance for summer/fall","whale_shark":"SNORKEL ONLY, no-touch, no scuba; licensed operator, 5 pax + guide per shark, 30-min limit; Oct 1-Apr 30 only","sea_lion":"SNORKEL ONLY, no-touch; Los Islotes closed Jun 1-Aug 31; keep guide distance from territorial bulls","dive":"nearest hyperbaric chamber in La Paz (verify status/location); DAN +1-919-684-9111; no-fly 18-24h; dive-within-cert; current on open-water sites","fcdo":{"posture":"AREA-RESTRICTED","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-08-20T14:49:02Z","page_updated":"2026-07-16T16:08:09+01:00","source_country":"mexico","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely","fcdo_zones":[{"name":"The city of Tijuana, in Baja California","lvl":3,"posture":"all-but-essential","except":["airside transit through Tijuana airport","the Cross Border Xpress bridge linking the airport across the border","federal toll road 1D and the Via Rápida through Tijuana to the border"]},{"name":"The city of Tecate in Baja California, including roads between Tijuana and Tecate","lvl":3,"posture":"all-but-essential"},{"name":"The state of Chihuahua","lvl":3,"posture":"all-but-essential","except":["the city of Chihuahua","the border crossing in Ciudad Juárez via federal toll road 45","federal toll road 45D between Chihuahua and Ciudad Juárez","the Copper Canyon rail route and the towns immediately on it, including Creel","the road from Creel via San Juanito to San Pedro","state highway 16 from San Pedro to Chihuahua"],"note":"The advisory also covers the areas south-west of road 45D."},{"name":"The state of Sinaloa","lvl":3,"posture":"all-but-essential","except":["the cities of Los Mochis and Mazatlán","road 32 between El Fuerte and Los Mochis","the 15D federal toll road running the length of the state","the Copper Canyon rail route to and from Los Mochis and El Fuerte, and the towns immediately on it"]},{"name":"The state of Tamaulipas","lvl":3,"posture":"all-but-essential","except":["the border crossing at Nuevo Laredo via federal toll road 85D from Monterrey","federal highways 80, 81 and 85 between Tampico, Ciudad Victoria and Magueyes","the area of Tamaulipas south of those highways"]},{"name":"The state of Zacatecas","lvl":3,"posture":"all-but-essential"},{"name":"In Guanajuato: the areas south-west of road 45D","lvl":3,"posture":"all-but-essential","note":"FCDO advises against all but essential travel to the areas south-west of road 45D. (San Miguel de Allende and Guanajuato City sit outside this area.)"},{"name":"The state of Michoacán","lvl":3,"posture":"all-but-essential","except":["the city of Morelia via federal toll roads 15D, 126 and 43","toll road 48D between Morelia and its airport","the town of Pátzcuaro via toll roads 14D and 15 from Morelia, and boat trips on Lake Pátzcuaro","Federal Highway 15D"]},{"name":"In Jalisco: the areas south and south-west of Lake Chapala to the Colima border","lvl":3,"posture":"all-but-essential","note":"Thirty-nine named municipalities, including Autlán de Navarro, Sayula, Tapalpa, Cocula and Villa Corona — the advisory lists each by name."},{"name":"In Jalisco: eleven northern municipalities","lvl":3,"posture":"all-but-essential","note":"Bolaños, Chimaltitán, Colotlán, Hostotipaquillo, Huejúcar, Huequilla el Alto, Mezquitic, San Martín de Bolaños, Santa María de los Ángeles, Totatiche and Villa Guerrero."},{"name":"The state of Colima","lvl":3,"posture":"all-but-essential","except":["the city of Manzanillo by sea, or by air via Manzanillo-Costalegre International Airport","direct travel via road 200 from that airport to Manzanillo"]},{"name":"The state of Guerrero, including the city of Acapulco","lvl":3,"posture":"all-but-essential","except":["the town of Zihuatanejo/Ixtapa accessed by air"]},{"name":"Within 40km of the Guatemalan border, from the Pacific Coast up to and including the Gracias a Dios crossing","lvl":3,"posture":"all-but-essential"},{"name":"Federal Highway 199 between Rancho Nuevo, outside San Cristóbal de las Casas, and the Chancalá junction outside Palenque","lvl":3,"posture":"all-but-essential","note":"The restriction is the highway segment, not the towns at either end."}],"fcdo_zones_provenance":{"file":"src/data/safety.json","ref":"f8666636bc25790e0c9643ad5656f8d9fea37bf6","ref_committed":"2026-08-30T05:44:55Z","country_iso2":"MX","summary":"The FCDO advises against all but essential travel to named states, cities and border areas of Mexico — listed below in its own words, each with its own exceptions. The Yucatán Peninsula, Mexico City, Baja California Sur and the other main visitor regions carry no FCDO restriction.","source":"UK FCDO — Mexico travel advice, reviewed 2026-07-16 (verbatim snapshot from the research library)","_rule":"the FCDO restricted-area records for this country, verbatim. PRESENCE OF THIS BLOCK IS NOT A CLAIM THAT THIS DESTINATION SITS IN ANY OF THEM — membership is a coverage judgement and is set only in `zone_record`, by a human."},"dive_emergency_numbers_verified":{"read":"2026-08-30","numbers":{"+1-919-684-9111":"DAN 24/7 emergency hotline — dan.org/about-dan/contact/, read 2026-08-30"},"_rule":"Each number above was read from the authority named beside it on the date shown. ⛔ A number with no entry here has NOT been verified and must not be presented as an emergency contact."}},"timing":{"peak":"Nov-Apr (dry desert winter); whale-shark event peak Oct 1-Apr 30 (core Nov-Mar)","shoulder":"May & Sep-early Oct (sea lions open, whale sharks bookending, warm water, softer rates)","green":"Jun-Aug (summer heat, hurricane window, whale sharks gone, sea-lion colony closed Jun 1-Aug 31)","out_of_season_fill_the_beds":"Balandra/Tecolote beaches, San Rafaelito reef (sea-lion substitute during closure), Malecon dining + sunset sails, Salvatierra wreck diving, boutique summer value rates","flag":"whale shark dead May-Sep; sea lions closed Jun 1-Aug 31; summer overlaps hurricane season Jun-Nov","sources":["https://www.thoroughlytravel.com/swim-with-whale-sharks-la-paz/","https://www.goworldtravel.com/snorkeling-sea-lions-sea-of-cortez/","https://scubaboard.com/community/threads/la-paz-sea-lion-colony-closed-for-snorkel-scuba-june-1-aug-31.621077/","https://www.islands.com/story/resorts/the-glamping-experience-of-isla-espiritu-santo-camp-cecil/"],"fire_date":"whale-shark/Espiritu Santo campaigns May-Jul (4-6 months ahead of Oct opening); Nov-Apr honeymoon/beach campaigns late summer; summer green-window value in spring","event_peaks":"Christmas-New Year, Semana Santa (Easter), whale-shark core Nov-Mar; domestic spikes Easter + mid-summer","booking_lead":"3-6 months for Nov-Apr peak; small boutique inventory (Baja Club 32 rooms, Camp Cecil 8 