  ('los-barriles-mexico', '10S', 'Los Barriles', 'Mexico', 'Los Barriles kiteboarding', 'live', 'verified', 'tropicalBeach', 'Baja California Sur (Los Cabos & La Paz)', '{"ocean","expedition","tropical"}', '{"tropical"}', '{"comfort","premier"}', null, null, '{"key_facts":["East Cape town on the Sea of Cortez, ~1 hr from Los Cabos Airport / ~40 min from La Paz","El Norte kite/wind season Nov 1 - end of March; N/NE crosswind 15-30 knots, afternoon peak","Offshore sportfishing peaks May-early November (marlin, sailfish, dorado, wahoo, tuna); glass-calm","Dorado Shoot Out (~mid-July, ~140 boats) is the largest dorado tournament in Baja; East Cape Offshore / Bisbee''s circuit opener nearby","Villas + fishing lodges are the lodging rung (Van Wormer Palmas de Cortez / Playa del Sol); northern gateway to Cabo Pulmo"],"safety":{"emergency":"911","hospital":"remote small town, no major trauma on-site; La Paz ~40 min (Hospital Salvatierra/private) or Los Cabos/San Jose del Cabo ~1 hr (private) - FLAG MEDEVAC DISTANCE; carry medical + evac insurance","malaria":"effectively none in Baja California Sur","dengue":"circulates in Mexico - use repellent","water":"drink bottled/purified water","hurricane":"Jun-Nov - trip insurance for summer/fall","wind_watersport":"El Norte 15-30 kt with offshore-drift risk - lessons with rescue-boat cover, correct kite size, helmet/impact vest for beginners","offshore_fishing":"open Sea of Cortez - licensed charter, VHF, life jackets, float plan, sun/heat protection; slow rescue on remote coast","dive":"diving south at Cabo Pulmo (separate dossier); nearest hyperbaric chamber Los Cabos or La Paz; no-fly 18-24h; DAN +1-919-684-9111; remote-distance flag","fcdo":{"posture":"AREA-RESTRICTED","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-08-20T14:49:02Z","page_updated":"2026-07-16T16:08:09+01:00","source_country":"mexico","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely","fcdo_zones":[{"name":"The city of Tijuana, in Baja California","lvl":3,"posture":"all-but-essential","except":["airside transit through Tijuana airport","the Cross Border Xpress bridge linking the airport across the border","federal toll road 1D and the Via Rápida through Tijuana to the border"]},{"name":"The city of Tecate in Baja California, including roads between Tijuana and Tecate","lvl":3,"posture":"all-but-essential"},{"name":"The state of Chihuahua","lvl":3,"posture":"all-but-essential","except":["the city of Chihuahua","the border crossing in Ciudad Juárez via federal toll road 45","federal toll road 45D between Chihuahua and Ciudad Juárez","the Copper Canyon rail route and the towns immediately on it, including Creel","the road from Creel via San Juanito to San Pedro","state highway 16 from San Pedro to Chihuahua"],"note":"The advisory also covers the areas south-west of road 45D."},{"name":"The state of Sinaloa","lvl":3,"posture":"all-but-essential","except":["the cities of Los Mochis and Mazatlán","road 32 between El Fuerte and Los Mochis","the 15D federal toll road running the length of the state","the Copper Canyon rail route to and from Los Mochis and El Fuerte, and the towns immediately on it"]},{"name":"The state of Tamaulipas","lvl":3,"posture":"all-but-essential","except":["the border crossing at Nuevo Laredo via federal toll road 85D from Monterrey","federal highways 80, 81 and 85 between Tampico, Ciudad Victoria and Magueyes","the area of Tamaulipas south of those highways"]},{"name":"The state of Zacatecas","lvl":3,"posture":"all-but-essential"},{"name":"In Guanajuato: the areas south-west of road 45D","lvl":3,"posture":"all-but-essential","note":"FCDO advises against all but essential travel to the areas south-west of road 45D. (San Miguel de Allende and Guanajuato City sit outside this area.)"},{"name":"The state of Michoacán","lvl":3,"posture":"all-but-essential","except":["the city of Morelia via federal toll roads 15D, 126 and 43","toll road 48D between Morelia and its airport","the town of Pátzcuaro via toll roads 14D and 15 from Morelia, and boat trips on Lake Pátzcuaro","Federal Highway 15D"]},{"name":"In Jalisco: the areas south and south-west of Lake Chapala to the Colima border","lvl":3,"posture":"all-but-essential","note":"Thirty-nine named municipalities, including Autlán de Navarro, Sayula, Tapalpa, Cocula and Villa Corona — the advisory lists each by name."},{"name":"In Jalisco: eleven northern municipalities","lvl":3,"posture":"all-but-essential","note":"Bolaños, Chimaltitán, Colotlán, Hostotipaquillo, Huejúcar, Huequilla el Alto, Mezquitic, San Martín de Bolaños, Santa María de los Ángeles, Totatiche and Villa Guerrero."},{"name":"The state of Colima","lvl":3,"posture":"all-but-essential","except":["the city of Manzanillo by sea, or by air via Manzanillo-Costalegre International Airport","direct travel via road 200 from that airport to Manzanillo"]},{"name":"The state of Guerrero, including the city of Acapulco","lvl":3,"posture":"all-but-essential","except":["the town of Zihuatanejo/Ixtapa accessed by air"]},{"name":"Within 40km of the Guatemalan border, from the Pacific Coast up to and including the Gracias a Dios crossing","lvl":3,"posture":"all-but-essential"},{"name":"Federal Highway 199 between Rancho Nuevo, outside San Cristóbal de las Casas, and the Chancalá junction outside Palenque","lvl":3,"posture":"all-but-essential","note":"The restriction is the highway segment, not the towns at either end."}],"fcdo_zones_provenance":{"file":"src/data/safety.json","ref":"f8666636bc25790e0c9643ad5656f8d9fea37bf6","ref_committed":"2026-08-30T05:44:55Z","country_iso2":"MX","summary":"The FCDO advises against all but essential travel to named states, cities and border areas of Mexico — listed below in its own words, each with its own exceptions. The Yucatán Peninsula, Mexico City, Baja California Sur and the other main visitor regions carry no FCDO restriction