id-July, East Cape Offshore) tightest; shoulder short-lead; verify current tournament dates"},"jewels":[{"name":"El Norte kiteboarding season (Nov-Mar)","si_tag":"Ocean Adventures","status":"future","tier":"premier","bookable":"Wahoo Wind Co. / Vela Baja lessons + rentals","source":"https://www.wahoowind.com/about","timing":"Nov-Mar","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"reliable 15–30 kt N/NE cross-wind on a protected sandy bay","si":"ocean","blurb":"reliable 15–30 kt N/NE cross-wind on a protected sandy bay","when":"Nov-Mar","commission":"kite-school operator on application + GYG affiliate","wells":[],"wells_basis":"text supports no Well — needs a human read","si_all":["ocean"],"shelf_fit":{"expedition":"destination","ocean":"primary","tropical":"destination"},"commission_lane":["operator","affiliate","school"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Wingfoil / windsurf clinics","si_tag":"Ocean Adventures","status":"future","tier":"premier","bookable":"local wind schools","source":"https://middlecasa.com/why-los-barriles-is-mexicos-winter-mecca-for-kitesurfers/","hook":"multi-day progression on the same El Norte wind","si":"ocean","blurb":"multi-day progression on the same El Norte wind","commission":"operator on application","wells":["activities"],"wells_basis":"pass 2 — text","si_all":["ocean"],"shelf_fit":{"expedition":"destination","ocean":"primary","tropical":"destination"},"commission_lane":["operator"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Offshore billfish/dorado charter","si_tag":"Ocean Adventures","status":"future","tier":"premier","bookable":"Van Wormer fleet / Charter Maria Teresa","source":"https://vanwormerresorts.com/sport-fishing","timing":"Nov-Mar","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"ocean","when":"Nov-Mar","commission":"charter on application","wells":[],"wells_basis":"text supports no Well — needs a human read","si_all":["ocean"],"shelf_fit":{"expedition":"destination","ocean":"primary","tropical":"destination"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed"},{"name":"Dorado Shoot Out tournament week","si_tag":"Ocean Adventures","status":"future","tier":"premier","bookable":"tournament entry + Palmas de Cortez lodging","source":"https://discoverbaja.com/2026/06/03/summer-2026-baja-fishing-tournaments/","timing":"Nov-Mar","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"~mid-July, ~140 boats, largest dorado tournament in Baja","si":"ocean","blurb":"~mid-July, ~140 boats, largest dorado tournament in Baja","when":"Nov-Mar","commission":"lodge/charter on application","wells":[],"wells_basis":"text supports no Well — needs a human read","si_all":["ocean"],"shelf_fit":{"expedition":"destination","ocean":"primary","tropical":"destination"},"commission_lane":["hotel"],"commission_embedded":false,"commission_basis":"lane"},{"name":"ATV / off-road desert + beach run","si_tag":"GEA","status":"live","tier":"comfort","bookable":"Los Barriles Adventures / local ATV operators","source":"https://www.tripadvisor.com/Attraction_Review-g1544261-d23230066-Reviews-Los_Barriles_Adventures-Los_Barriles_Baja_California.html","hook":"quad rides into the sierra to remote beaches, snorkel coves, historic lighthouse","si":"expedition","blurb":"quad rides into the sierra to remote beaches, snorkel coves, historic lighthouse","commission":"operator + Viator affiliate","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["expedition","tropical"],"shelf_fit":{"expedition":"primary","ocean":"destination","tropical":"evidenced"},"commission_lane":["operator","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Winter whale watching (offshore)","si_tag":"GEA","status":"live","tier":"comfort","bookable":"local boat operators / Amstar","source":"https://sallysees.com/whale-watching-in-baja-california-sur/","si":"expedition","commission":"operator + affiliate","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["expedition"],"shelf_fit":{"expedition":"primary","ocean":"destination","tropical":"destination"},"commission_lane":["operator","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"La Paz whale-shark day trip","si_tag":"GEA","status":"live","tier":"premier","bookable":"La Paz operator day trip + transfer","source":"https://www.cabopulmopark.com/","si":"expedition","commission":"operator + Viator affiliate","wells":["activities"],"wells_basis":"pass 2 — text","si_all":["expedition"],"shelf_fit":{"expedition":"primary","ocean":"destination","tropical":"destination"},"commission_lane":["operator","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Calm-water Sea of Cortez beach day (off-wind season)","si_tag":"Tropical Islands","status":"future","tier":"comfort","bookable":"villa + local SUP/snorkel rental","source":"https://www.globeguide.ca/travel-guide-los-barriles-mexico/","hook":"swim/snorkel/SUP the warm gulf when El Norte is down","si":"tropical","blurb":"swim/snorkel/SUP the warm gulf when El Norte is down","commission":"rental + villa","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["tropical"],"shelf_fit":{"expedition":"destination","ocean":"destination","tropical":"primary"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed"}],"faq":[{"q":"When is kiteboarding season in Los Barriles?","a":"November 1 to the end of March, when the \"El Norte\" wind blows a reliable 15–30 kt N/NE crosswind, building mid-morning and peaking in the afternoon. The wide, protected sandy bay suits all levels — book instructors and beachfront villas 4–9 months out.","source":"wahoowind.com, 2026-07-04","si_tag":"ocean"},{"q":"When is the fishing best, and what''s the big tournament?","a":"Offshore peaks May to early November in glass-calm water for marlin, dorado, wahoo and tuna, and the marquee event is the mid-July Dorado Shoot Out — ~140 boats, Baja''s largest dorado tournament. Kite and fishing are opposite seasons, so plan for one or the other.","source":"vanwormerresorts.com / discoverbaja.com, 2026-07-04","si_tag":"ocean"},{"q":"What else is there beyond wind and fish?","a":"Winter whale-watching (Dec–Apr) offshore, ATV desert-and-beach runs year-round, and the La Paz whale-shark snorkel ~40 minutes north (Oct–Apr). Off the wind season (Apr–Oct) the Sea of Cortez turns calm for swimming, snorkel and SUP.","source":"sallysees.com / globeguide.ca, 2026-07-04","si_tag":"expedition"},{"q":"Is kiteboarding here dangerous?","a":"It''s for the prepared — the core hazard is offshore drift. El Norte''s 15–30 kt N/NE wind is side-offshore, so a downed kiter drifts toward open sea; take lessons with a school running rescue-boat cover, use the right kite size and self-rescue skills, and check the daily wind before launch.","source":"wahoowind.com, 2026-07-04","si_tag":"safety"}],"seo":{"meta_title":"Los Barriles Mexico: Kiteboarding, Fishing & El Norte Winds 2026","meta_description":"Los Barriles on Baja''s East Cape — El Norte kiteboarding season (Nov–Mar), world-class marlin/dorado sportfishing, villas, ATV desert runs and the gateway to Cabo Pulmo.","slug":"los-barriles-mexico","primary_keyword":"Los Barriles kiteboarding","long_tail":["Los Barriles El Norte wind season","Los Barriles sportfishing dorado marlin","Dorado Shoot Out tournament Los Barriles","Los Barriles East Cape villa rentals","kitesurfing Los Barriles vs La Ventana"],"search_language":["en","es-MX"],"local_keywords":["Los Barriles kitesurf temporada El Norte","pesca deportiva Los Barriles dorado marlin","torneo Dorado Shoot Out Los Barriles","villas renta Los Barriles Baja","clases de kite Los Barriles","qué hacer en Los Barriles","Los Barriles cómo llegar desde Los Cabos"],"hreflang":["en","es-MX"],"jsonld_type":"TouristDestination","content_freshness":"2026-07-04","attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-07-04","last_verified_basis":"source_verified","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-08-20T14:49:02Z","source_updated":"2026-07-16T16:08:09+01:00"}]}},"booking":{"advisory_updated":"2026-08-20","advisory_authority":"FCDO"},"si_checklist_25":null,"sis_present":[{"si":"ocean","status":"future"},{"si":"GEA (Great Escapes & Adventures)","status":"live"},{"si":"tropical","status":"future"}],"ultra":[{"name":"Hotel Palmas de Cortez (Van Wormer)","posture":"premier fishing resort + tournament host in-town; not five-star brand","price_tier":"premier","earning":"on application via host / DMC","virtuoso_value_add":"n/a-branded - treat as premier fishing lodge","mor":"no net-rate resale","source":"https://vanwormerresorts.com/"},{"name":"Premier beachfront villas (Punta Pescadero / Los Barriles)","posture":"top private-stay rung locally for wind-week/fishing groups","price_tier":"luxury","earning":"on application via host / villa manager","virtuoso_value_add":"private villa + kite/fishing days brought in","mor":"agency terms, no net-rate resale","source":"https://abajavacation.com/"}],"source_verified":"2026-07-04","hero":{"query":"Los Barriles, Mexico"},"geo":{"lat":23.682,"lng":-109.696},"orbit":[{"id":"balandra-beach-mexico","jewels":5,"si":["tropical","family","romance"]},{"id":"cabo-pulmo-mexico","jewels":5,"si":["expedition","diveglobal"]},{"id":"cabo-san-lucas-mexico","jewels":6,"si":["liveaboard","expedition","ocean","ultra"]},{"id":"east-cape-m